#[test]
fn remove_reinsert_and_release() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::Create {
                id: 3,
                tag: Tag::View,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: None,
            },
        ],
    );
    c.commit().unwrap();

    // Move 3 before 2: a single insert, no remove.
    c.apply(Op::Insert {
        parent: ROOT_ID,
        child: 3,
        before: Some(2),
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert!(matches!(
        batch.items[0],
        MountItem::Insert {
            child: 3,
            before: Some(2),
            ..
        }
    ));
    assert!(
        !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Remove { .. }))
    );

    c.apply(Op::Remove {
        parent: ROOT_ID,
        child: 2,
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert!(matches!(batch.items[0], MountItem::Remove { id: 2 }));

    // Reinserting a detached, already-created view does not recreate it.
    c.apply(Op::Insert {
        parent: ROOT_ID,
        child: 2,
        before: None,
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert!(
        !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Create { .. }))
    );

    c.apply(Op::Release { id: 2 }).unwrap();
    let batch = c.commit().unwrap();
    assert!(
        batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Delete { id: 2 }))
    );
    assert_eq!(c.node_count(), 2);
    assert_eq!(
        c.apply(Op::SetText {
            id: 2,
            text: String::new()
        }),
        Err(ApplyError::UnknownNode(2))
    );
}

#[test]
fn events_and_errors() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            Op::Listen {
                id: 2,
                event: EventKind::Press,
                enabled: true,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(
        |i| matches!(i, MountItem::Events { id: 2, events } if events.contains(EventKind::Press))
    ));
    assert_eq!(
        c.apply(Op::Create {
            id: 2,
            tag: Tag::View
        }),
        Err(ApplyError::DuplicateNode(2))
    );
    assert_eq!(
        c.apply(Op::Insert {
            parent: 2,
            child: ROOT_ID,
            before: None
        }),
        Err(ApplyError::Cycle(1))
    );
}

#[test]
fn color_change_skips_layout_and_identical_texts_share_measurements() {
    let mut c = core();
    let mut ops = Vec::new();
    for i in 0..3u32 {
        let (block, raw) = (10 + i * 2, 11 + i * 2);
        ops.extend([
            Op::Create {
                id: block,
                tag: Tag::Text,
            },
            Op::CreateText {
                id: raw,
                text: "same".into(),
            },
            Op::Insert {
                parent: block,
                child: raw,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: block,
                before: None,
            },
        ]);
    }
    apply(&mut c, ops);
    let batch = c.commit().unwrap();
    // Three identical texts: measured once per distinct constraint.
    let first_measures = c.text_engine.measures.get();
    assert!(first_measures <= 2, "measured {first_measures} times");
    assert_eq!(c.text_engine.layouts.get(), 3);
    let content = batch.items.iter().find_map(|i| match i {
        MountItem::Text {
            id: 10, content, ..
        } => Some(*content),
        _ => None,
    });
    assert_eq!(content, Some(rect(0.0, 0.0, 320.0, 16.0)));

    c.apply(style_op(10, &[("color", StyleValue::Str("red"))]))
        .unwrap();
    let batch = c.commit().unwrap();
    assert_eq!(
        batch.items.len(),
        1,
        "only the new text layout: {:?}",
        batch.items
    );
    assert!(matches!(&batch.items[0], MountItem::Text { id: 10, .. }));
    assert_eq!(
        c.text_engine.measures.get(),
        first_measures,
        "no re-measure"
    );
    assert_eq!(c.text_engine.layouts.get(), 4);
}

/// A text block (10) of three words, each a span of its own (12, 14, 16;
/// their raw texts 13, 15, 17), on an engine that draws colors from the
/// text or not; `ops` run before the block's first commit.
fn three_words(colors_at_draw: bool, ops: Vec<Op>) -> Core<FakeEngine> {
    let mut c = Core::new(
        FakeEngine {
            colors_at_draw,
            ..FakeEngine::default()
        },
        size_pt(320.0, 480.0),
    );
    let mut block = vec![Op::Create {
        id: 10,
        tag: Tag::Text,
    }];
    for (i, word) in ["fade ", "in ", "words"].into_iter().enumerate() {
        let (span, raw) = (12 + i as u32 * 2, 13 + i as u32 * 2);
        block.extend([
            Op::Create {
                id: span,
                tag: Tag::Text,
            },
            Op::CreateText {
                id: raw,
                text: word.into(),
            },
            Op::Insert {
                parent: span,
                child: raw,
                before: None,
            },
            Op::Insert {
                parent: 10,
                child: span,
                before: None,
            },
        ]);
    }
    block.push(Op::Insert {
        parent: ROOT_ID,
        child: 10,
        before: None,
    });
    block.extend(ops);
    apply(&mut c, block);
    c
}

/// The text block 10 mounted in `batch`: its text, layout and content box.
fn mounted_words(batch: &MountBatch) -> Option<(Arc<AttributedText>, TextLayout, Bounds<Points>)> {
    batch.items.iter().find_map(|i| match i {
        MountItem::Text {
            id: 10,
            text,
            layout,
            content,
        } => Some((text.clone(), layout.clone(), *content)),
        _ => None,
    })
}

/// How many times the engine typeset, measured and laid out a text.
fn engine_counts(c: &Core<FakeEngine>) -> (u32, u32, u32) {
    let e = &c.text_engine;
    (e.prepares.get(), e.measures.get(), e.layouts.get())
}

#[test]
fn colors_drawn_from_the_text_keep_its_typesetting() {
    let mut c = three_words(true, Vec::new());
    let mounted = mounted_words;
    let counts = engine_counts;
    let (_, first, content) = mounted(&c.commit().unwrap()).expect("mounted");
    let before = counts(&c);
    let color = |c: &mut Core<FakeEngine>, id, color| {
        c.apply(style_op(id, &[("color", StyleValue::Str(color))]))
            .unwrap();
        c.commit().unwrap()
    };
    // A word fading in: a new color, the same span boundaries.
    let batch = color(&mut c, 14, "rgba(255, 0, 0, 0.5)");
    assert_eq!(batch.items.len(), 1, "only the text: {:?}", batch.items);
    let (text, layout, moved) = mounted(&batch).expect("the new text mounted");
    assert_eq!(text.spans[1].style.color, Color(0xff00_0080));
    assert!(Arc::ptr_eq(&layout.0, &first.0), "the layout drawn before");
    assert_eq!(moved, content);
    assert_eq!(counts(&c), before, "no typesetting, measuring or layout");
    // Its neighbors take its color: the three spans merge into one.
    color(&mut c, 12, "rgba(255, 0, 0, 0.5)");
    let batch = color(&mut c, 16, "rgba(255, 0, 0, 0.5)");
    let (text, layout, _) = mounted(&batch).expect("the new text mounted");
    assert_eq!(text.spans.len(), 1);
    assert!(Arc::ptr_eq(&layout.0, &first.0));
    assert_eq!(counts(&c), before);
    // A change of size is typeset again.
    c.apply(style_op(14, &[("fontSize", StyleValue::Number(20.0))]))
        .unwrap();
    let (_, layout, _) = mounted(&c.commit().unwrap()).expect("the new text mounted");
    assert!(!Arc::ptr_eq(&layout.0, &first.0));
    assert!(c.text_engine.prepares.get() > before.0);
}

#[test]
fn hidden_words_drawn_from_the_text_keep_its_typesetting() {
    let visibility = |id, v| style_op(id, &[("visibility", StyleValue::Str(v))]);
    // The last two words are queued: hidden, in their place in the lines.
    let mut c = three_words(
        true,
        vec![visibility(14, "hidden"), visibility(16, "hidden")],
    );
    let (text, first, content) = mounted_words(&c.commit().unwrap()).expect("mounted");
    assert_eq!(text.visible_text(), "fade ");
    let before = engine_counts(&c);
    let show = |c: &mut Core<FakeEngine>, ops: Vec<Op>| {
        apply(c, ops);
        let batch = c.commit().unwrap();
        assert_eq!(batch.items.len(), 1, "only the text: {:?}", batch.items);
        mounted_words(&batch).expect("the new text mounted")
    };
    // A word starts: shown, as a color would change, with the layout
    // already drawn and nothing typeset, measured or laid out again.
    let (text, layout, moved) = show(&mut c, vec![visibility(14, "visible")]);
    assert_eq!(text.visible_text(), "fade in ");
    assert!(Arc::ptr_eq(&layout.0, &first.0), "the layout drawn before");
    assert_eq!(moved, content);
    assert_eq!(engine_counts(&c), before);
    // The next one starts in a color of its own, and is hidden again.
    let fading = vec![
        visibility(16, "visible"),
        style_op(16, &[("color", StyleValue::Str("rgba(255, 0, 0, 0.5)"))]),
    ];
    let (text, layout, _) = show(&mut c, fading);
    assert_eq!(text.visible_text(), "fade in words");
    assert!(Arc::ptr_eq(&layout.0, &first.0));
    let (text, layout, _) = show(&mut c, vec![visibility(16, "hidden")]);
    assert_eq!(text.visible_text(), "fade in ");
    assert!(Arc::ptr_eq(&layout.0, &first.0));
    assert_eq!(engine_counts(&c), before);
    // New characters, or a new size, are typeset again.
    c.apply(Op::SetText {
        id: 17,
        text: "word".into(),
    })
    .unwrap();
    let (_, layout, _) = mounted_words(&c.commit().unwrap()).expect("the new text mounted");
    assert!(!Arc::ptr_eq(&layout.0, &first.0));
    let typeset = engine_counts(&c).0;
    assert!(typeset > before.0);
    apply(
        &mut c,
        vec![style_op(16, &[("fontSize", StyleValue::Number(20.0))])],
    );
    mounted_words(&c.commit().unwrap()).expect("the new text mounted");
    assert!(engine_counts(&c).0 > typeset);
}

#[test]
fn hidden_words_are_typeset_again_where_colors_are_typeset() {
    let mut c = three_words(
        false,
        vec![style_op(14, &[("visibility", StyleValue::Str("hidden"))])],
    );
    let (_, first, _) = mounted_words(&c.commit().unwrap()).expect("mounted");
    let before = engine_counts(&c);
    apply(
        &mut c,
        vec![style_op(14, &[("visibility", StyleValue::Str("visible"))])],
    );
    let (text, layout, _) = mounted_words(&c.commit().unwrap()).expect("the new text mounted");
    assert!(!text.has_hidden());
    assert!(!Arc::ptr_eq(&layout.0, &first.0));
    assert!(engine_counts(&c).0 > before.0, "typeset again");
}

#[test]
fn spans_differing_only_in_colors_are_told_apart_from_other_changes() {
    let style = ResolvedTextStyle::default();
    let red = ResolvedTextStyle {
        color: Color(0xff00_00ff),
        ..style
    };
    let text = |words: &[(&str, ResolvedTextStyle)]| {
        let mut t = AttributedText::default();
        for &(w, s) in words {
            t.push(w, s);
        }
        t
    };
    let plain = text(&[("ab", style), ("cd", style)]);
    let split = text(&[("ab", style), ("cd", red)]);
    assert_eq!((plain.spans.len(), split.spans.len()), (1, 2));
    assert!(plain.same_but_colors(&split) && split.same_but_colors(&plain));
    let bold = ResolvedTextStyle {
        font_weight: 700,
        ..red
    };
    assert!(!plain.same_but_colors(&text(&[("ab", style), ("cd", bold)])));
    assert!(!plain.same_but_colors(&text(&[("ab", style), ("ce", red)])));
    let underlined = ResolvedTextStyle {
        decoration: crate::TextDecoration {
            underline: true,
            ..Default::default()
        },
        ..style
    };
    assert!(!plain.same_but_colors(&text(&[("abcd", underlined)])));
    let lined = |color| ResolvedTextStyle {
        decoration_color: color,
        ..underlined
    };
    let green = Some(Color(0x00ff_00ff));
    assert!(text(&[("ab", lined(None))]).same_but_colors(&text(&[("ab", lined(green))])));
    // Hidden characters keep their place: a run hidden or shown again is
    // only drawn differently, as one recolored.
    let hidden = text(&[("ab", style), ("cd", red.hide())]);
    assert!(plain.same_but_colors(&hidden) && hidden.same_but_colors(&split));
    assert!(!hidden.same_but_colors(&text(&[("ab", style), ("cd", bold.hide())])));
}

#[test]
fn recolored_ranges_are_the_characters_drawn_otherwise() {
    let style = ResolvedTextStyle::default();
    let red = ResolvedTextStyle {
        color: Color(0xff00_00ff),
        ..style
    };
    let bold = ResolvedTextStyle {
        font_weight: 700,
        ..style
    };
    let text = |words: &[(&str, ResolvedTextStyle)]| {
        let mut t = AttributedText::default();
        for &(w, s) in words {
            t.push(w, s);
        }
        t
    };
    let words = |styles: [ResolvedTextStyle; 5]| {
        text(&[
            ("one ", styles[0]),
            ("two ", styles[1]),
            ("three ", styles[2]),
            ("four ", styles[3]),
            ("five", styles[4]),
        ])
    };
    // The ranges, written as pairs.
    let ranges = |pairs: &[(u32, u32)]| Some(pairs.iter().map(|&(a, b)| a..b).collect::<Vec<_>>());
    let plain = words([style; 5]);
    // Nothing drawn otherwise, however the spans split.
    assert_eq!(plain.recolored_ranges(&plain), ranges(&[]));
    let same = text(&[("one two ", style), ("three four five", style)]);
    assert_eq!(plain.recolored_ranges(&same), ranges(&[]));
    // A word shown: its characters; neighbors join into one range.
    let fading = words([style, style, style, red.hide(), red.hide()]);
    assert_eq!(fading.recolored_ranges(&plain), ranges(&[(14, 23)]));
    let started = words([style, style, style, red, red.hide()]);
    assert_eq!(fading.recolored_ranges(&started), ranges(&[(14, 19)]));
    // Apart: two ranges, either way round.
    let apart = words([red, style, style, red, style]);
    assert_eq!(plain.recolored_ranges(&apart), ranges(&[(0, 4), (14, 19)]));
    assert_eq!(apart.recolored_ranges(&plain), ranges(&[(0, 4), (14, 19)]));
    // Spans that start and end elsewhere in the two texts.
    let halves = text(&[("one two th", red), ("ree four five", style)]);
    assert_eq!(plain.recolored_ranges(&halves), ranges(&[(0, 10)]));
    // Anything else changed: not a recoloring.
    assert_eq!(
        plain.recolored_ranges(&words([style, bold, style, style, style])),
        None
    );
    assert_eq!(plain.recolored_ranges(&text(&[("one", style)])), None);
}

#[test]
fn image_uses_natural_size_and_aspect_ratio() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Image,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Source(Some(ImageSource {
                    uri: "asset:/logo.png".into(),
                    size: Some(size_pt(200.0, 100.0)),
                    scales: ImageScales::NONE,
                    data: None,
                })),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            Op::Create {
                id: 3,
                tag: Tag::Image,
            },
            style_op(
                3,
                &[
                    ("width", StyleValue::Number(50.0)),
                    ("alignSelf", StyleValue::Str("flex-start")),
                ],
            ),
            Op::SetProp {
                id: 3,
                prop: Prop::Source(Some(ImageSource {
                    uri: "asset:/logo.png".into(),
                    size: Some(size_pt(200.0, 100.0)),
                    scales: ImageScales::NONE,
                    data: None,
                })),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(|i| matches!(
        i,
        MountItem::Create {
            id: 2,
            kind: ViewKind::Image
        }
    )));
    assert!(batch.items.iter().any(|i| matches!(
        i,
        MountItem::Image {
            id: 2,
            source: Some(_),
            ..
        }
    )));
    // Stretched to the column width, height from the aspect ratio.
    assert_eq!(
        frame_of(&batch, 2).map(|f| (f.size.width.0, f.size.height.0)),
        Some((320.0, 160.0))
    );
    assert_eq!(
        frame_of(&batch, 3).map(|f| (f.size.width.0, f.size.height.0)),
        Some((50.0, 25.0))
    );
}

#[test]
fn object_position_reaches_the_image_item_only() {
    let mut c = core();
    let mut ops = image_ops(2, asset("asset:/a.png", &[]), None);
    ops.push(style_op(2, &[("objectPosition", StyleValue::Str("top"))]));
    apply(&mut c, ops);
    let batch = c.commit().unwrap();
    let position = |batch: &MountBatch| {
        batch.items.iter().rev().find_map(|i| match i {
            MountItem::Image { id: 2, options, .. } => Some(options.position),
            _ => None,
        })
    };
    let top = crate::style::ObjectPosition::parse("top").unwrap();
    assert_eq!(position(&batch), Some(top));
    // A change sends the image again, and no view style.
    apply(
        &mut c,
        vec![style_op(
            2,
            &[("objectPosition", StyleValue::Str("right 10px bottom 0"))],
        )],
    );
    let batch = c.commit().unwrap();
    assert_eq!(
        position(&batch),
        crate::style::ObjectPosition::parse("right 10px bottom 0")
    );
    assert!(
        !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::ViewStyle { .. })),
        "{:?}",
        batch.items
    );
    // An invalid value is rejected, not misread.
    let mut style = crate::Style::default();
    assert!(
        style
            .set("objectPosition", StyleValue::Str("left 10px top"))
            .is_err()
    );
}

#[test]
fn object_fit_is_a_style_classes_and_styles_share() {
    let mut c = core();
    let mut ops = image_ops(2, asset("asset:/a.png", &[]), None);
    ops.push(class_op(2, "object-contain"));
    apply(&mut c, ops);
    let fit = |batch: &MountBatch| {
        batch.items.iter().rev().find_map(|i| match i {
            MountItem::Image {
                id: 2, resize_mode, ..
            } => Some(*resize_mode),
            _ => None,
        })
    };
    assert_eq!(fit(&c.commit().unwrap()), Some(ResizeMode::Contain));
    // The style wins over the class, as in CSS; CSS's `fill` stretches.
    apply(
        &mut c,
        vec![style_op(2, &[("objectFit", StyleValue::Str("fill"))])],
    );
    assert_eq!(fit(&c.commit().unwrap()), Some(ResizeMode::Stretch));
    // Unset, the class's again; without it the image's default.
    apply(&mut c, vec![style_op(2, &[])]);
    assert_eq!(fit(&c.commit().unwrap()), Some(ResizeMode::Contain));
    apply(&mut c, vec![class_op(2, "")]);
    assert_eq!(fit(&c.commit().unwrap()), Some(ResizeMode::Cover));
    let mut style = crate::Style::default();
    assert!(style.set("objectFit", StyleValue::Str("stretch")).is_err());
}

#[test]
fn resize_modes_fit_at_their_position() {
    use crate::{ResizeMode, geometry::size_pt, style::ObjectPosition};
    let tall = size_pt(100.0, 300.0);
    let square = size_pt(100.0, 100.0);
    let at = |mode: ResizeMode, p: &str| {
        let b = mode.fit(tall, square, ObjectPosition::parse(p).unwrap());
        (b.origin.x.0, b.origin.y.0, b.size.width.0, b.size.height.0)
    };
    assert_eq!(at(ResizeMode::Cover, "center"), (0.0, -100.0, 100.0, 300.0));
    assert_eq!(at(ResizeMode::Cover, "top"), (0.0, 0.0, 100.0, 300.0));
    assert_eq!(at(ResizeMode::Cover, "bottom"), (0.0, -200.0, 100.0, 300.0));
    let half = |p: &str| {
        let b = ResizeMode::Contain.fit(
            size_pt(50.0, 100.0),
            square,
            ObjectPosition::parse(p).unwrap(),
        );
        (b.origin.x.0, b.origin.y.0, b.size.width.0, b.size.height.0)
    };
    assert_eq!(half("left"), (0.0, 0.0, 50.0, 100.0));
    assert_eq!(half("right"), (50.0, 0.0, 50.0, 100.0));
    assert_eq!(half("25%"), (12.5, 0.0, 50.0, 100.0));
    assert_eq!(
        at(ResizeMode::Stretch, "left top"),
        (0.0, 0.0, 100.0, 100.0)
    );
    // CSS's `object-fit: none` keeps the natural size, cropped where
    // larger; `scale-down` shrinks what does not fit. Both keep the
    // natural size of what fits, at the position.
    assert_eq!(
        at(ResizeMode::Center, "center"),
        (0.0, -100.0, 100.0, 300.0)
    );
    assert_eq!(at(ResizeMode::Center, "top"), (0.0, 0.0, 100.0, 300.0));
    let shrunk = ResizeMode::ScaleDown.fit(size_pt(200.0, 400.0), square, ObjectPosition::CENTER);
    assert_eq!(
        (
            shrunk.origin.x.0,
            shrunk.origin.y.0,
            shrunk.size.width.0,
            shrunk.size.height.0
        ),
        (25.0, 0.0, 50.0, 100.0)
    );
    for mode in [ResizeMode::Center, ResizeMode::ScaleDown] {
        let small = mode.fit(size_pt(20.0, 10.0), square, ObjectPosition::CENTER);
        assert_eq!(
            (small.origin.x.0, small.origin.y.0, small.size.width.0),
            (40.0, 45.0, 20.0)
        );
        let corner = mode.fit(
            size_pt(20.0, 10.0),
            square,
            ObjectPosition::parse("right bottom").unwrap(),
        );
        assert_eq!((corner.origin.x.0, corner.origin.y.0), (80.0, 90.0));
    }
}

#[test]
fn native_components_get_their_name_props_and_size() {
    let mut c = core();
    let prop = |name: &str, value: Option<crate::JsonValue>| Op::SetProp {
        id: 2,
        prop: Prop::ComponentProp(name.into(), value),
    };
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Native,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Component("com.example.map".into()),
            },
            prop("zoom", Some(serde_json::json!(3))),
            prop("center", Some(serde_json::json!({ "lat": 1.5, "lng": 2 }))),
            style_op(2, &[("alignSelf", StyleValue::Str("flex-start"))]),
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    let at = |pred: &dyn Fn(&MountItem) -> bool| batch.items.iter().position(pred);
    let create = at(&|i| {
        matches!(
            i,
            MountItem::Create {
                id: 2,
                kind: ViewKind::Native
            }
        )
    })
    .unwrap();
    let component =
        at(&|i| matches!(i, MountItem::Component { id: 2, name } if &**name == "com.example.map"))
            .unwrap();
    let props = batch
        .items
        .iter()
        .position(|i| matches!(i, MountItem::ComponentProps { id: 2, .. }))
        .unwrap();
    assert!(create < component && component < props);
    let MountItem::ComponentProps { props: all, .. } = &batch.items[props] else {
        unreachable!()
    };
    assert_eq!(all.len(), 2);
    assert!(all.contains(&(
        "center".into(),
        Some(serde_json::json!({ "lat": 1.5, "lng": 2 }))
    )));
    // No size of its own yet.
    assert_eq!(
        frame_of(&batch, 2).map(|f| (f.size.width.0, f.size.height.0)),
        Some((0.0, 0.0))
    );

    // Only what changed; removals as `None`.
    apply(
        &mut c,
        vec![
            prop("zoom", Some(serde_json::json!(4))),
            prop("center", None),
        ],
    );
    let batch = c.commit().unwrap();
    let changed: Vec<_> = batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::ComponentProps { id: 2, props } => Some(props.clone()),
            _ => None,
        })
        .collect();
    assert_eq!(
        changed,
        [vec![
            ("zoom".into(), Some(serde_json::json!(4))),
            ("center".into(), None)
        ]]
    );

    // The size it reports lays it out.
    c.set_component_size(2, size_pt(120.0, 40.0));
    let batch = c.commit().unwrap();
    assert_eq!(
        frame_of(&batch, 2).map(|f| (f.size.width.0, f.size.height.0)),
        Some((120.0, 40.0))
    );
}

#[test]
fn scroll_reports_content_size() {
    let mut c = core();
    let mut ops = vec![
        Op::Create {
            id: 2,
            tag: Tag::Scroll,
        },
        style_op(2, &[("height", StyleValue::Number(200.0))]),
        Op::Insert {
            parent: ROOT_ID,
            child: 2,
            before: None,
        },
    ];
    for i in 0..5u32 {
        ops.push(Op::Create {
            id: 10 + i,
            tag: Tag::View,
        });
        ops.push(style_op(10 + i, &[("height", StyleValue::Number(100.0))]));
        ops.push(Op::Insert {
            parent: 2,
            child: 10 + i,
            before: None,
        });
    }
    apply(&mut c, ops);
    let batch = c.commit().unwrap();
    let content = batch.items.iter().find_map(|i| match i {
        MountItem::ScrollContent { id: 2, size } => Some(*size),
        _ => None,
    });
    assert_eq!(content, Some(size_pt(320.0, 500.0)));
    // Children are not shrunk to the scroll view's height (the last one,
    // beyond a viewport below it, is laid out but not mounted yet).
    assert_eq!(
        frame_of(&batch, 13).map(|f| (f.origin.y.0, f.size.height.0)),
        Some((300.0, 100.0))
    );
    assert_eq!(frame_of(&batch, 14), None);
    assert_eq!(
        c.measure(14)
            .map(|m| (m.frame.origin.y.0, m.frame.size.height.0)),
        Some((400.0, 100.0))
    );
    assert!(batch.items.iter().any(|i| matches!(
        i,
        MountItem::ScrollConfig {
            id: 2,
            horizontal: false,
            ..
        }
    )));
}

/// `overflow: "hidden"` clips in layout as well as in paint: what a box
/// clips away must not grow an ancestor scroll view's content size. A
/// preview laid out at its design width and scaled down by a transform
/// (transforms do not affect layout) otherwise leaves a vertical scroll
/// view scrollable sideways.
#[test]
fn clipped_overflow_does_not_grow_scroll_content() {
    /// The content width of a 320pt-wide vertical scroll view holding a
    /// 300pt box, itself holding a 400pt-wide absolute child.
    fn content_width(clips: bool) -> f32 {
        let mut c = core();
        let mut boxed = vec![
            ("width", StyleValue::Number(300.0)),
            ("height", StyleValue::Number(100.0)),
        ];
        if clips {
            boxed.push(("overflow", StyleValue::Str("hidden")));
        }
        apply(
            &mut c,
            vec![
                Op::Create {
                    id: 2,
                    tag: Tag::Scroll,
                },
                style_op(2, &[("height", StyleValue::Number(200.0))]),
                Op::Insert {
                    parent: ROOT_ID,
                    child: 2,
                    before: None,
                },
                Op::Create {
                    id: 3,
                    tag: Tag::View,
                },
                style_op(3, &boxed),
                Op::Insert {
                    parent: 2,
                    child: 3,
                    before: None,
                },
                Op::Create {
                    id: 4,
                    tag: Tag::View,
                },
                style_op(
                    4,
                    &[
                        ("position", StyleValue::Str("absolute")),
                        ("left", StyleValue::Number(0.0)),
                        ("top", StyleValue::Number(0.0)),
                        ("width", StyleValue::Number(400.0)),
                        ("height", StyleValue::Number(50.0)),
                    ],
                ),
                Op::Insert {
                    parent: 3,
                    child: 4,
                    before: None,
                },
            ],
        );
        let batch = c.commit().unwrap();
        batch
            .items
            .iter()
            .find_map(|i| match i {
                MountItem::ScrollContent { id: 2, size } => Some(size.width.0),
                _ => None,
            })
            .expect("scroll content size")
    }
    // Visible: the 400pt child reaches the scroll view, which scrolls to it.
    assert_eq!(content_width(false), 400.0);
    // Clipped: the scroll view keeps its own width, so it does not scroll
    // sideways at all.
    assert_eq!(content_width(true), 320.0);
}

/// A scroll view's content size set twice in one batch (a row relaid in
/// two passes) reaches the platform once, with the last size: a transient
/// smaller size would clamp the offset before the content grows back.
#[test]
fn scroll_content_is_sent_once_per_batch() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Scroll,
            },
            style_op(2, &[("height", StyleValue::Number(200.0))]),
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    c.commit();
    let key = c.key(2).unwrap();
    c.set_scroll_content(key, size_pt(320.0, 277.0));
    c.set_scroll_content(key, size_pt(320.0, 909.0));
    let sizes: Vec<_> = c
        .mount
        .iter()
        .filter_map(|i| match i {
            MountItem::ScrollContent { id: 2, size } => Some(size.height.0),
            _ => None,
        })
        .collect();
    assert_eq!(sizes, [909.0]);
    // The next batch sends its own.
    c.mount.clear();
    c.batches += 1;
    c.set_scroll_content(key, size_pt(320.0, 300.0));
    assert!(matches!(
        c.mount[..],
        [MountItem::ScrollContent { id: 2, .. }]
    ));
}

/// Native scroll commands see the old extent before a shrink and the new
/// extent before growth. A change of cross size must not override that.
#[test]
fn scroll_content_preserves_the_extent_each_scroll_command_needs() {
    for horizontal in [false, true] {
        for absolute in [false, true] {
            for (next_length, shrinking) in [(500.0, true), (900.0, false), (1200.0, false)] {
                let mut c = core();
                apply(
                    &mut c,
                    vec![
                        Op::Create {
                            id: 2,
                            tag: Tag::Scroll,
                        },
                        Op::SetProp {
                            id: 2,
                            prop: Prop::Horizontal(horizontal),
                        },
                        Op::Insert {
                            parent: ROOT_ID,
                            child: 2,
                            before: None,
                        },
                    ],
                );
                c.commit();
                let key = c.key(2).unwrap();
                let dimensions = |length, cross| {
                    if horizontal {
                        size_pt(length, cross)
                    } else {
                        size_pt(cross, length)
                    }
                };
                let old = dimensions(900.0, 320.0);
                let new = dimensions(next_length, 200.0);
                c.set_scroll_content(key, old);
                c.mount.push(if absolute {
                    MountItem::Command {
                        id: 2,
                        command: Command::ScrollTo {
                            x: px(50.0),
                            y: px(50.0),
                            animated: false,
                        },
                    }
                } else {
                    MountItem::ScrollBy {
                        id: 2,
                        dx: px(50.0),
                        dy: px(50.0),
                    }
                });
                c.set_scroll_content(key, new);
                let sizes: Vec<_> = c
                    .mount
                    .iter()
                    .enumerate()
                    .filter_map(|(at, item)| match item {
                        MountItem::ScrollContent { id: 2, size } => Some((at, *size)),
                        _ => None,
                    })
                    .collect();
                if shrinking {
                    assert_eq!(c.mount.len(), 3);
                    assert_eq!(sizes, [(0, old), (2, new)]);
                } else {
                    assert_eq!(c.mount.len(), 2);
                    assert_eq!(sizes, [(0, new)]);
                }
            }
        }
    }
}

/// Plays JS: creates a cell per new slot, renders a fixed-height
/// row for each bind and confirms the index; the overscan too, as an
/// engine with time to spare does.
fn render_binds(
    c: &mut Core<FakeEngine>,
    next_id: &mut u32,
    cells: &mut Vec<u32>,
    row_height: f32,
) -> usize {
    render_list_binds(c, next_id, cells, row_height, usize::MAX)
}

/// [`render_binds`] with at most `paced` of the overscan's waiting binds,
/// as an engine short of time.
fn render_list_binds(
    c: &mut Core<FakeEngine>,
    next_id: &mut u32,
    cells: &mut Vec<u32>,
    row_height: f32,
    paced: usize,
) -> usize {
    render_sized_binds(c, next_id, cells, &|_| row_height, paced)
}

/// [`render_list_binds`] with row `index` `row_height(index)` points
/// tall.
fn render_sized_binds(
    c: &mut Core<FakeEngine>,
    next_id: &mut u32,
    cells: &mut Vec<u32>,
    row_height: &dyn Fn(u32) -> f32,
    paced: usize,
) -> usize {
    let mut binds = Vec::new();
    c.take_list_binds(&mut binds);
    c.take_paced_list_binds(paced, &mut binds);
    let mut count = 0;
    for bind in binds {
        for (slot, index) in bind.binds {
            count += 1;
            while cells.len() <= slot as usize {
                let id = *next_id;
                *next_id += 1;
                apply(
                    c,
                    vec![
                        Op::Create { id, tag: Tag::Cell },
                        Op::SetProp {
                            id,
                            prop: Prop::Slot(CellSlot::Item(cells.len() as u32)),
                        },
                        Op::Insert {
                            parent: bind.list,
                            child: id,
                            before: None,
                        },
                    ],
                );
                cells.push(id);
            }
            // New content for the item, then the confirmation, as the
            // runtime does.
            let cell = cells[slot as usize];
            c.apply(style_op(
                cell,
                &[("height", StyleValue::Number(row_height(index)))],
            ))
            .unwrap();
            c.apply(Op::SetProp {
                id: cell,
                prop: Prop::CellIndex(index),
            })
            .unwrap();
        }
    }
    count
}

#[test]
fn list_renders_window_and_recycles_cells() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::List,
            },
            style_op(2, &[("height", StyleValue::Number(400.0))]),
            Op::SetProp {
                id: 2,
                prop: Prop::EstimatedItemSize(px(50.0)),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Count(1000),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    // Estimated 50 pt rows: viewport + one screen of overscan = 17 rows.
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 100.0), 17);
    let batch = c.commit().unwrap();
    // Rows are really 100 pt: positioned by measured sizes.
    assert_eq!(
        frame_of(&batch, cells[3]),
        Some(rect(0.0, 300.0, 320.0, 100.0))
    );
    let content = batch.items.iter().rev().find_map(|i| match i {
        MountItem::ScrollContent { id: 2, size } => Some(size.height.0),
        _ => None,
    });
    assert_eq!(content, Some(17.0 * 100.0 + 983.0 * 50.0));

    // Scroll far down into unmeasured (50 pt estimated) rows: the window
    // needs 25 rows; all 17 existing cells are reused and 8 are added.
    c.set_scroll_offset(2, point(px(0.0), px(10_000.0)), u32::MAX);
    c.commit();
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 25);
    assert_eq!(cells.len(), 25);
    c.commit();
    // Scrolling on reuses cells only.
    c.set_scroll_offset(2, point(px(0.0), px(20_000.0)), u32::MAX);
    c.commit();
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 25);
    assert_eq!(cells.len(), 25);
    c.commit();
    assert_eq!(c.node_count(), 2 + cells.len());
}

/// With tree order tracked (a platform's focus traversal), a list's
/// recycled cells come in the order they are on screen, not in the order
/// they were made, and their moves send the order again.
#[test]
fn tracked_tree_order_puts_a_lists_cells_in_screen_order() {
    let mut c = core();
    c.set_tree_order_tracking(true);
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::List,
            },
            style_op(2, &[("height", StyleValue::Number(400.0))]),
            Op::SetProp {
                id: 2,
                prop: Prop::EstimatedItemSize(px(50.0)),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Count(1000),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let mut order = Vec::new();
    let mut take = |batch: Option<MountBatch>| {
        for item in batch.into_iter().flat_map(|b| b.items) {
            if let MountItem::TreeOrder(nodes) = item {
                order = nodes;
            }
        }
    };
    take(c.commit());
    let (mut next_id, mut cells) = (100, Vec::new());
    render_binds(&mut c, &mut next_id, &mut cells, 50.0);
    take(c.commit());
    for y in [600.0, 300.0, 1500.0, 900.0, 2400.0, 1700.0] {
        c.set_scroll_offset(2, point(px(0.0), px(y)), u32::MAX);
        take(c.commit());
        render_binds(&mut c, &mut next_id, &mut cells, 50.0);
        take(c.commit());
    }
    let shown: Vec<u32> = order
        .iter()
        .copied()
        .filter(|id| cells.contains(id))
        .collect();
    assert_eq!(shown.len(), cells.len());
    let y = |id: &u32| c.nodes[c.key(*id).unwrap() as usize].frame.origin.y.0;
    assert!(shown.windows(2).all(|w| y(&w[0]) <= y(&w[1])), "{shown:?}");
    // The cells were recycled out of the order they were made in.
    assert_ne!(shown, cells);
}

/// Plays a list's scroll view on the platform: applies the scrolls the
/// core sends it, clamped to its content, counting them as a platform
/// does.
#[derive(Default)]
struct ScrollingPlatform {
    y: f32,
    applied: u32,
    content: f32,
}

impl ScrollingPlatform {
    /// Applies what `batch` sends list `id` of `viewport` points;
    /// whether it scrolled.
    fn apply(&mut self, batch: &MountBatch, id: NodeId, viewport: f32) -> bool {
        let mut scrolled = false;
        for item in &batch.items {
            match item {
                MountItem::ScrollContent { id: i, size } if *i == id => {
                    self.content = size.height.0;
                }
                MountItem::ScrollBy { id: i, dy, .. } if *i == id => {
                    self.y += dy.0;
                    self.applied += 1;
                    scrolled = true;
                }
                MountItem::Command {
                    id: i,
                    command: Command::ScrollTo { y, .. },
                } if *i == id => {
                    self.y = y.0;
                    self.applied += 1;
                    scrolled = true;
                }
                _ => {}
            }
            self.y = self.y.clamp(0.0, (self.content - viewport).max(0.0));
        }
        scrolled
    }

    /// Commits and renders the rows list 2 binds, row `index`
    /// `row_height(index)` tall, reporting the scrolls it applies, until
    /// nothing changes.
    fn settle(
        &mut self,
        c: &mut Core<FakeEngine>,
        next_id: &mut u32,
        cells: &mut Vec<u32>,
        row_height: &dyn Fn(u32) -> f32,
    ) {
        for _ in 0..50 {
            let batch = c.commit();
            let scrolled = batch.as_ref().is_some_and(|b| self.apply(b, 2, 400.0));
            if scrolled {
                c.set_scroll_offset(2, point(px(0.0), px(self.y)), self.applied);
            }
            let bound = render_sized_binds(c, next_id, cells, row_height, usize::MAX);
            if batch.is_none() && !scrolled && bound == 0 {
                return;
            }
        }
        panic!("the list never settled");
    }
}

/// What `ref.measureScrollPosition()` of node `id` answers.
fn scroll_position(c: &mut Core<FakeEngine>, id: NodeId) -> crate::JsonValue {
    c.apply(Op::Command {
        id,
        command: Command::MeasureScrollPosition { call: 7 },
    })
    .unwrap();
    c.commit();
    js_events(c)
        .into_iter()
        .find_map(|(_, _, payload)| match payload {
            EventPayload::Native { name, data } if &*name == "$return" && data["c"] == 7 => {
                Some(data["v"].clone())
            }
            _ => None,
        })
        .expect("an answer")
}

/// The row list 2 lays out at content offset `y`, and how far into it
/// `y` is, from the frames of its cells.
fn row_laid_out_at(c: &Core<FakeEngine>, y: f32) -> (u32, f32) {
    let list = c.nodes[c.key(2).unwrap() as usize].list.as_ref().unwrap();
    list.slots
        .iter()
        .filter_map(|s| s.ready().map(|index| (index, s.cell)))
        .find_map(|(index, cell)| {
            let frame = c.nodes[cell as usize].frame;
            let (top, height) = (frame.origin.y.0, frame.size.height.0);
            (top <= y && y < top + height).then_some((index, y - top))
        })
        .expect("a row at the offset")
}

/// After a jump far into rows laid out by their estimate and corrected
/// as they are measured, and a scroll, the list says which row the
/// viewport starts in and how far into it, as its cells are laid out
/// (rows above measured and estimated alike); scrolling a list made anew
/// to that row, that far, puts the viewport's start back there.
#[test]
fn a_list_measures_where_its_viewport_starts_among_its_rows() {
    let row_height = |index: u32| 30.0 + (index * 37 % 7) as f32 * 15.0;
    let open = |c: &mut Core<FakeEngine>| {
        thousand_rows(c);
        let (mut next_id, mut cells) = (100, Vec::new());
        let mut platform = ScrollingPlatform::default();
        platform.settle(c, &mut next_id, &mut cells, &row_height);
        (next_id, cells, platform)
    };
    let mut c = core();
    let (mut next_id, mut cells, mut platform) = open(&mut c);
    assert_eq!(
        scroll_position(&mut c, 2),
        serde_json::json!({ "index": 0, "offset": 0.0 })
    );
    assert_eq!(scroll_position(&mut c, ROOT_ID), crate::JsonValue::Null);

    c.apply(Op::Command {
        id: 2,
        command: Command::ScrollToIndex {
            index: 400,
            animated: false,
            automatic: false,
            view_position: crate::geometry::Percentage(0.0),
            view_offset: px(0.0),
        },
    })
    .unwrap();
    platform.settle(&mut c, &mut next_id, &mut cells, &row_height);
    assert_eq!(row_laid_out_at(&c, platform.y), (400, 0.0));
    // Measured rows replaced their estimates on the way.
    assert_ne!(platform.y, 400.0 * 50.0);
    platform.y += 70.0;
    c.set_scroll_offset(2, point(px(0.0), px(platform.y)), platform.applied);
    platform.settle(&mut c, &mut next_id, &mut cells, &row_height);

    let (index, offset) = row_laid_out_at(&c, platform.y);
    assert!(offset > 0.0, "{index} {offset}");
    let at = scroll_position(&mut c, 2);
    assert_eq!(at, serde_json::json!({ "index": index, "offset": offset }));

    // A list made anew restores it with `scrollToIndex`.
    let mut c = core();
    let (mut next_id, mut cells, mut platform) = open(&mut c);
    c.apply(Op::Command {
        id: 2,
        command: Command::ScrollToIndex {
            index,
            animated: false,
            automatic: false,
            view_position: crate::geometry::Percentage(0.0),
            view_offset: px(-offset),
        },
    })
    .unwrap();
    platform.settle(&mut c, &mut next_id, &mut cells, &row_height);
    assert_eq!(row_laid_out_at(&c, platform.y), (index, offset));
    assert_eq!(scroll_position(&mut c, 2), at);
}

#[test]
fn list_keeps_visible_content_anchored() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::List,
            },
            style_op(2, &[("height", StyleValue::Number(400.0))]),
            Op::SetProp {
                id: 2,
                prop: Prop::EstimatedItemSize(px(50.0)),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Count(100),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    c.commit();
    // Jump into the middle before anything above was measured.
    c.set_scroll_offset(2, point(px(0.0), px(2000.0)), u32::MAX);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    render_binds(&mut c, &mut next_id, &mut cells, 50.0);
    c.commit();
    // Scroll back up so rows above the old position get rendered at 80 pt.
    c.set_scroll_offset(2, point(px(0.0), px(1200.0)), u32::MAX);
    c.commit();
    render_binds(&mut c, &mut next_id, &mut cells, 80.0);
    let batch = c.commit().unwrap();
    let shift: f32 = batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::ScrollBy { id: 2, dy, .. } => Some(dy.0),
            _ => None,
        })
        .sum();
    assert!(
        shift > 0.0,
        "rows above the viewport grew; content must be shifted down"
    );
}

/// Whether `batch` last hid view `id` from sight (`visibility: hidden`)
/// and from screen readers, if it sent either.
fn hidden_in(batch: &MountBatch, id: NodeId) -> (Option<bool>, Option<bool>) {
    let style = batch.items.iter().rev().find_map(|i| match i {
        MountItem::ViewStyle { id: i, style } if *i == id => Some(style.hidden),
        _ => None,
    });
    let props = batch.items.iter().rev().find_map(|i| match i {
        MountItem::ViewProps { id: i, props } if *i == id => Some(props.accessibility.hidden),
        _ => None,
    });
    (style, props)
}

/// A list of 1000 rows estimated at 50 pt in a 400 pt viewport.
fn thousand_rows(c: &mut Core<FakeEngine>) {
    apply(
        c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::List,
            },
            style_op(2, &[("height", StyleValue::Number(400.0))]),
            Op::SetProp {
                id: 2,
                prop: Prop::EstimatedItemSize(px(50.0)),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Count(1000),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
}

#[test]
fn spare_list_cells_are_hidden_until_placed_again() {
    let mut c = core();
    thousand_rows(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 17);
    let batch = c.commit().unwrap();
    for &cell in &cells {
        assert_eq!(
            hidden_in(&batch, cell),
            (None, None),
            "cell {cell} shows its row"
        );
    }

    // The data shrinks: the cells left without a row still show their
    // last one, so they are hidden as well as moved out of sight.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(3),
        }],
    );
    let batch = c.commit().unwrap();
    for &cell in &cells[..3] {
        assert_eq!(
            hidden_in(&batch, cell),
            (None, None),
            "cell {cell} keeps its row"
        );
    }
    for (row, &cell) in cells.iter().enumerate().skip(3) {
        assert_eq!(
            hidden_in(&batch, cell),
            (Some(true), Some(true)),
            "spare cell {cell}"
        );
        // Those in the render window (to 800 pt) move out of sight too.
        let moved = (row < 16).then_some(-1.0e6);
        assert_eq!(
            frame_of(&batch, cell).map(|f| f.origin.y.0),
            moved,
            "spare cell {cell}"
        );
    }

    // It grows again: the cells come back with their new rows.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(1000),
        }],
    );
    c.commit();
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 14);
    let batch = c.commit().unwrap();
    let mut rows: Vec<f32> = cells[3..]
        .iter()
        .map(|&cell| {
            assert_eq!(
                hidden_in(&batch, cell),
                (Some(false), Some(false)),
                "cell {cell}"
            );
            frame_of(&batch, cell).expect("placed").origin.y.0
        })
        .collect();
    rows.sort_by(f32::total_cmp);
    assert_eq!(
        rows,
        (3..17).map(|row| 50.0 * row as f32).collect::<Vec<_>>()
    );

    // Far down, the window takes all 17 cells and 8 more; back at the
    // top, the 8 it no longer needs stay where the window left them,
    // showing their own rows there, out of sight. Screen readers skip the
    // cells the window left behind (the rows there may have moved since
    // they were laid out) until their new rows are bound: nothing else is
    // mounted before.
    c.set_scroll_offset(2, point(px(0.0), px(10_000.0)), u32::MAX);
    c.commit();
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 25);
    c.commit();
    c.set_scroll_offset(2, point(px(0.0), px(0.0)), u32::MAX);
    let left = c.commit().expect("the cells left behind");
    for &cell in &cells {
        assert_eq!(hidden_in(&left, cell), (None, Some(true)), "cell {cell}");
        assert_eq!(frame_of(&left, cell), None, "cell {cell}");
    }
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 17);
    let placed = c.commit().unwrap();
    let mut spare = Vec::new();
    for &cell in &cells {
        match frame_of(&placed, cell) {
            Some(frame) => {
                assert!(frame.origin.y.0 <= 800.0, "cell {cell} at {frame:?}");
                assert_eq!(hidden_in(&placed, cell), (None, Some(false)), "cell {cell}");
            }
            None => {
                assert_eq!(hidden_in(&placed, cell), (None, None), "cell {cell}");
                spare.push(cell);
            }
        }
    }
    assert_eq!(spare.len(), 8);
    // Once the items change, the rows they show may be gone: hidden.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(999),
        }],
    );
    let batch = c.commit().unwrap();
    for &cell in &cells {
        let hidden = if spare.contains(&cell) {
            Some(true)
        } else {
            None
        };
        assert_eq!(hidden_in(&batch, cell), (hidden, hidden), "cell {cell}");
        assert_eq!(frame_of(&batch, cell), None, "cell {cell}");
    }
}

#[test]
fn scrolling_on_hides_no_cells() {
    let mut c = core();
    thousand_rows(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    // 70 pt rows estimated at 50: the cells made for the rows that do
    // not fit after all are hidden.
    let mut hidden = Vec::new();
    for _ in 0..2 {
        render_binds(&mut c, &mut next_id, &mut cells, 70.0);
        let Some(batch) = c.commit() else { continue };
        for &cell in &cells {
            match hidden_in(&batch, cell).0 {
                Some(true) => hidden.push(cell),
                Some(false) => hidden.retain(|&h| h != cell),
                None => {}
            }
        }
    }
    assert!(!hidden.is_empty());
    // Then the window loses a row at one end before it gains one at the
    // other (1200 pt is no multiple of 70), which takes the cell left
    // behind: no cell is hidden, those hidden are shown once reused.
    let mut at = 0.0;
    while at < 3000.0 {
        at += 10.0;
        c.set_scroll_offset(2, point(px(0.0), px(at)), u32::MAX);
        let mut batches: Vec<MountBatch> = c.commit().into_iter().collect();
        render_binds(&mut c, &mut next_id, &mut cells, 70.0);
        batches.extend(c.commit());
        for batch in &batches {
            for &cell in &cells {
                match hidden_in(batch, cell).0 {
                    None => {}
                    Some(false) if hidden.contains(&cell) => hidden.retain(|&h| h != cell),
                    other => panic!("cell {cell} at {at}: {other:?}"),
                }
            }
        }
    }
    assert!(hidden.is_empty(), "{hidden:?}");
}

#[test]
fn list_cells_unbound_before_they_are_placed_are_hidden() {
    let mut c = core();
    thousand_rows(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 17);
    // The data shrinks before the new cells were placed: those without a
    // row show the content made for it, with no frame to move them away.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(3),
        }],
    );
    let batch = c.commit().unwrap();
    for (row, &cell) in cells.iter().enumerate() {
        if row < 3 {
            assert_eq!(hidden_in(&batch, cell), (None, None), "cell {cell}");
            assert!(frame_of(&batch, cell).is_some());
        } else {
            assert_eq!(
                hidden_in(&batch, cell),
                (Some(true), Some(true)),
                "cell {cell}"
            );
            assert_eq!(frame_of(&batch, cell), None, "cell {cell} was never placed");
        }
    }
}

#[test]
fn spare_list_cells_waiting_for_a_paced_bind_show_when_it_lands() {
    let mut c = core();
    thousand_rows(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 17);
    c.commit();
    // Shrunk to 3 rows, the other 14 cells are hidden; grown back, the
    // viewport's rows bind at once and the overscan's wait.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(3),
        }],
    );
    c.commit();
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::Count(1000),
        }],
    );
    c.commit();
    assert_eq!(
        render_list_binds(&mut c, &mut next_id, &mut cells, 50.0, 0),
        5
    );
    assert!(c.has_paced_list_binds());
    let batch = c.commit().unwrap();
    let mut waiting = Vec::new();
    for &cell in &cells[3..] {
        match hidden_in(&batch, cell) {
            (Some(false), Some(false)) => {
                assert!(frame_of(&batch, cell).is_some(), "cell {cell}")
            }
            // Still hidden, out of sight, until its bind lands.
            (None, None) => {
                assert_eq!(frame_of(&batch, cell), None, "cell {cell}");
                waiting.push(cell);
            }
            other => panic!("cell {cell}: {other:?}"),
        }
    }
    assert_eq!(waiting.len(), 9);
    // The paced binds land: those cells show, at their rows.
    assert_eq!(render_binds(&mut c, &mut next_id, &mut cells, 50.0), 9);
    assert!(!c.has_paced_list_binds());
    let batch = c.commit().unwrap();
    let mut rows: Vec<f32> = waiting
        .iter()
        .map(|&cell| {
            assert_eq!(
                hidden_in(&batch, cell),
                (Some(false), Some(false)),
                "cell {cell}"
            );
            frame_of(&batch, cell).expect("placed").origin.y.0
        })
        .collect();
    rows.sort_by(f32::total_cmp);
    assert_eq!(
        rows,
        (8..17).map(|row| 50.0 * row as f32).collect::<Vec<_>>()
    );
}

/// A list of 100 rows estimated at 50 pt in a 400 pt viewport.
fn estimated_list(c: &mut Core<FakeEngine>) {
    apply(
        c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::List,
            },
            style_op(2, &[("height", StyleValue::Number(400.0))]),
            Op::SetProp {
                id: 2,
                prop: Prop::EstimatedItemSize(px(50.0)),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Count(100),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
}

/// Where list 2 is after `batch`: from `start`, its `ScrollTo` commands
/// and `ScrollBy` items in order.
fn scrolled(batch: &MountBatch, start: f32) -> f32 {
    batch.items.iter().fold(start, |at, item| match item {
        MountItem::Command {
            id: 2,
            command: Command::ScrollTo { y, .. },
        } => y.0,
        MountItem::ScrollBy { id: 2, dy, .. } => at + dy.0,
        _ => at,
    })
}

#[test]
fn bottom_aligned_list_does_not_mount_scrolls_during_native_bounce() {
    let mut c = core();
    estimated_list(&mut c);
    apply(
        &mut c,
        vec![
            Op::SetProp {
                id: 2,
                prop: Prop::ListAlignment(crate::ListAlignment::Bottom),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::FollowEnd(Some(px(80.0))),
            },
        ],
    );
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    for _ in 0..3 {
        render_binds(&mut c, &mut next_id, &mut cells, 50.0);
        c.commit();
    }
    for offset in [4610.0, 4630.0, 4660.0, 4630.0, 4610.0, 4600.0] {
        c.set_scroll_offset(2, point(px(0.0), px(offset)), u32::MAX);
        if let Some(batch) = c.commit() {
            assert_eq!(scrolled(&batch, offset), offset, "native offset {offset}");
        }
    }
}

#[test]
fn scroll_commands_follow_their_target_as_rows_are_measured() {
    let mut c = core();
    estimated_list(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    render_binds(&mut c, &mut next_id, &mut cells, 50.0);
    c.commit();
    // The rows are really 80 pt: the end of the estimated content is too
    // early, and the list follows the end once the last rows measure.
    c.apply(Op::Command {
        id: 2,
        command: Command::ScrollToEnd { animated: false },
    })
    .unwrap();
    let mut at = scrolled(&c.commit().unwrap(), 0.0);
    for _ in 0..4 {
        render_binds(&mut c, &mut next_id, &mut cells, 80.0);
        if let Some(batch) = c.commit() {
            at = scrolled(&batch, at);
        }
    }
    let key = c.key(2).unwrap();
    let content = c.nodes[key as usize]
        .scroll
        .as_ref()
        .unwrap()
        .content
        .unwrap();
    assert_eq!(at, (content.height - Points(400.0)).0);

    // Item 50 in the middle of the viewport.
    c.apply(Op::Command {
        id: 2,
        command: Command::ScrollToIndex {
            index: 50,
            animated: false,
            automatic: false,
            view_position: crate::geometry::Percentage(0.5),
            view_offset: px(0.0),
        },
    })
    .unwrap();
    at = scrolled(&c.commit().unwrap(), at);
    for _ in 0..4 {
        render_binds(&mut c, &mut next_id, &mut cells, 80.0);
        if let Some(batch) = c.commit() {
            at = scrolled(&batch, at);
        }
    }
    let list = c.nodes[key as usize].list.as_ref().unwrap();
    assert_eq!(list.item_at(50) + 40.0 - at, 200.0);
    assert!(!list.pinned(), "settled");

    // Scrolled by the user, the list stays where it is put.
    c.set_scroll_offset(2, point(px(0.0), px(at - 600.0)), u32::MAX);
    c.commit();
    assert!(render_binds(&mut c, &mut next_id, &mut cells, 120.0) > 0);
    let batch = c.commit().unwrap();
    assert!(
        !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Command { id: 2, .. })),
        "no scroll command after the user scrolled"
    );
}

#[test]
fn animated_scroll_commands_retarget_while_rows_are_measured() {
    let mut c = core();
    estimated_list(&mut c);
    c.commit();
    let (mut next_id, mut cells) = (100, Vec::new());
    render_binds(&mut c, &mut next_id, &mut cells, 80.0);
    c.commit();
    c.apply(Op::Command {
        id: 2,
        command: Command::ScrollToEnd { animated: true },
    })
    .unwrap();
    let first = scrolled(&c.commit().unwrap(), 0.0);
    let mut target = first;
    // The platform starts the animation; the window follows it to the
    // end, whose rows are measured: the animation is retargeted.
    c.set_scroll_offset(2, point(px(0.0), px(1000.0)), 1);
    c.commit();
    c.set_scroll_offset(2, point(px(0.0), px(first - 10.0)), 1);
    c.commit();
    let mut issued = 1;
    for _ in 0..4 {
        render_binds(&mut c, &mut next_id, &mut cells, 80.0);
        if let Some(batch) = c.commit() {
            for item in &batch.items {
                if let MountItem::Command {
                    id: 2,
                    command: Command::ScrollTo { y, animated, .. },
                } = item
                {
                    assert!(animated);
                    target = y.0;
                    issued += 1;
                }
            }
        }
    }
    assert!(issued > 1 && target > first, "retargeted");
    let key = c.key(2).unwrap();
    let content = c.nodes[key as usize]
        .scroll
        .as_ref()
        .unwrap()
        .content
        .unwrap();
    assert_eq!(target, (content.height - Points(400.0)).0);
}

#[test]
fn animated_background_colors_replace_gradients() {
    let mut c = core();
    let mut s = Style::default();
    s.set_background_images(vec![crate::effects::Gradient {
        kind: crate::effects::GradientKind::Linear {
            angle: crate::geometry::deg(180.0),
        },
        stops: Vec::new(),
        repeating: false,
    }]);
    s.animated.push((AnimationProp::BackgroundColor, 7));
    apply(
        &mut c,
        vec![
            Op::Animation(AnimationOp::CreateValue {
                node: 7,
                value: 1.0,
            }),
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 2,
                style: Box::new(s),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(view_style_of(&batch, 2).is_none_or(|s| s.effects.is_none()));
}

#[test]
fn animation_ops_and_bindings_are_forwarded_in_order() {
    let mut c = core();
    let mut s = Style::default();
    s.animated.push((AnimationProp::Opacity, 7));
    apply(
        &mut c,
        vec![
            Op::Animation(AnimationOp::CreateValue {
                node: 7,
                value: 1.0,
            }),
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 2,
                style: Box::new(s),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    let animation = batch.items.iter().position(|i| {
        matches!(
            i,
            MountItem::Animation(AnimationOp::CreateValue { node: 7, .. })
        )
    });
    let bind = batch
        .items
        .iter()
        .position(|i| matches!(i, MountItem::AnimationBindings { id: 2, .. }));
    assert!(
        animation.unwrap() < bind.unwrap(),
        "values exist before views bind them"
    );
}

#[test]
fn leaf_styles_are_resolved() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            // Text with padding: the frame wraps the measured text.
            Op::Create {
                id: 2,
                tag: Tag::Text,
            },
            style_op(2, &[("padding", StyleValue::Number(10.0))]),
            Op::CreateText {
                id: 3,
                text: "abc".into(),
            },
            Op::Insert {
                parent: 2,
                child: 3,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            // Empty leaf view: min size and aspect ratio still apply.
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            style_op(
                4,
                &[
                    ("width", StyleValue::Number(100.0)),
                    ("aspectRatio", StyleValue::Number(2.0)),
                    ("alignSelf", StyleValue::Str("flex-start")),
                ],
            ),
            Op::Insert {
                parent: ROOT_ID,
                child: 4,
                before: None,
            },
            Op::Create {
                id: 5,
                tag: Tag::View,
            },
            style_op(5, &[("minHeight", StyleValue::Number(80.0))]),
            Op::Insert {
                parent: ROOT_ID,
                child: 5,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(
        frame_of(&batch, 2).map(|f| f.size.height.0),
        Some(16.0 + 20.0)
    );
    let content = batch.items.iter().find_map(|i| match i {
        MountItem::Text { id: 2, content, .. } => Some(*content),
        _ => None,
    });
    assert_eq!(content, Some(rect(10.0, 10.0, 300.0, 16.0)));
    assert_eq!(
        frame_of(&batch, 4).map(|f| (f.size.width.0, f.size.height.0)),
        Some((100.0, 50.0))
    );
    assert_eq!(frame_of(&batch, 5).map(|f| f.size.height.0), Some(80.0));
}

/// `cargo test --release -p nsh-core bench_row_relayout -- --ignored --nocapture`
#[test]
#[ignore]
fn bench_row_relayout() {
    let mut c = core();
    // A gallery-like row: [image] [title / author] in a list cell.
    let row = |s: &[(&str, StyleValue<'_>)]| style(s);
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 2,
                style: row(&[
                    ("flexDirection", StyleValue::Str("row")),
                    ("alignItems", StyleValue::Str("center")),
                    ("gap", StyleValue::Number(12.0)),
                    ("padding", StyleValue::Number(8.0)),
                ]),
                patch: StylePatch::default(),
            },
            Op::Create {
                id: 3,
                tag: Tag::Image,
            },
            Op::SetStyle {
                id: 3,
                style: row(&[
                    ("width", StyleValue::Number(48.0)),
                    ("height", StyleValue::Number(48.0)),
                ]),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: 2,
                child: 3,
                before: None,
            },
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 4,
                style: row(&[("flex", StyleValue::Number(1.0))]),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: 2,
                child: 4,
                before: None,
            },
            Op::Create {
                id: 5,
                tag: Tag::Text,
            },
            Op::CreateText {
                id: 6,
                text: "Photo #1".into(),
            },
            Op::Insert {
                parent: 5,
                child: 6,
                before: None,
            },
            Op::Insert {
                parent: 4,
                child: 5,
                before: None,
            },
            Op::Create {
                id: 7,
                tag: Tag::Text,
            },
            Op::CreateText {
                id: 8,
                text: "by Ada".into(),
            },
            Op::Insert {
                parent: 7,
                child: 8,
                before: None,
            },
            Op::Insert {
                parent: 4,
                child: 7,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    c.commit();
    let n = 2000;
    let start = std::time::Instant::now();
    for i in 0..n {
        c.apply(Op::SetText {
            id: 6,
            text: format!("Photo #{i}"),
        })
        .unwrap();
        c.apply(Op::SetText {
            id: 8,
            text: format!("by {}", ["Ada", "Ken"][i % 2]),
        })
        .unwrap();
        c.commit();
    }
    eprintln!("row relayout: {:?} per commit", start.elapsed() / n as u32);
}

/// `cargo test --release -p nsh-core bench_cell_relayout -- --ignored --nocapture`
#[test]
#[ignore]
fn bench_cell_relayout() {
    let mut c = Core::new(crate::ApproxTextEngine, size_pt(390.0, 800.0));
    let s = |p: &[(&str, StyleValue<'_>)]| style(p);
    let mut ops = vec![
        Op::Create {
            id: 2,
            tag: Tag::List,
        },
        Op::SetStyle {
            id: 2,
            style: s(&[("flex", StyleValue::Number(1.0))]),
            patch: StylePatch::default(),
        },
        Op::SetProp {
            id: 2,
            prop: Prop::EstimatedItemSize(px(64.0)),
        },
        Op::SetProp {
            id: 2,
            prop: Prop::Count(1000),
        },
        Op::Insert {
            parent: ROOT_ID,
            child: 2,
            before: None,
        },
    ];
    for op in std::mem::take(&mut ops) {
        c.apply(op).unwrap();
    }
    c.commit();
    let mut binds = Vec::new();
    c.take_list_binds(&mut binds);
    // One cell with a gallery row.
    for op in [
        Op::Create {
            id: 10,
            tag: Tag::Cell,
        },
        Op::SetProp {
            id: 10,
            prop: Prop::Slot(CellSlot::Item(0)),
        },
        Op::Insert {
            parent: 2,
            child: 10,
            before: None,
        },
        Op::Create {
            id: 11,
            tag: Tag::View,
        },
        Op::SetStyle {
            id: 11,
            style: s(&[
                ("flexDirection", StyleValue::Str("row")),
                ("alignItems", StyleValue::Str("center")),
                ("gap", StyleValue::Number(12.0)),
                ("paddingHorizontal", StyleValue::Number(16.0)),
                ("paddingVertical", StyleValue::Number(8.0)),
            ]),
            patch: StylePatch::default(),
        },
        Op::Insert {
            parent: 10,
            child: 11,
            before: None,
        },
        Op::Create {
            id: 12,
            tag: Tag::Image,
        },
        Op::SetStyle {
            id: 12,
            style: s(&[
                ("width", StyleValue::Number(48.0)),
                ("height", StyleValue::Number(48.0)),
            ]),
            patch: StylePatch::default(),
        },
        Op::Insert {
            parent: 11,
            child: 12,
            before: None,
        },
        Op::Create {
            id: 13,
            tag: Tag::View,
        },
        Op::SetStyle {
            id: 13,
            style: s(&[
                ("flex", StyleValue::Number(1.0)),
                ("gap", StyleValue::Number(2.0)),
            ]),
            patch: StylePatch::default(),
        },
        Op::Insert {
            parent: 11,
            child: 13,
            before: None,
        },
        Op::Create {
            id: 14,
            tag: Tag::Text,
        },
        Op::CreateText {
            id: 15,
            text: "Photo #1".into(),
        },
        Op::Insert {
            parent: 14,
            child: 15,
            before: None,
        },
        Op::Insert {
            parent: 13,
            child: 14,
            before: None,
        },
        Op::Create {
            id: 16,
            tag: Tag::Text,
        },
        Op::CreateText {
            id: 17,
            text: "by Ada".into(),
        },
        Op::Insert {
            parent: 16,
            child: 17,
            before: None,
        },
        Op::Insert {
            parent: 13,
            child: 16,
            before: None,
        },
        Op::SetProp {
            id: 10,
            prop: Prop::CellIndex(0),
        },
    ] {
        c.apply(op).unwrap();
    }
    c.commit();
    for idle in [0u64, 10] {
        let n = if idle == 0 { 2000 } else { 100 };
        let mut total = std::time::Duration::ZERO;
        for i in 0..n {
            std::thread::sleep(std::time::Duration::from_millis(idle));
            let start = std::time::Instant::now();
            c.apply(Op::SetText {
                id: 15,
                text: format!("Photo #{i}"),
            })
            .unwrap();
            c.apply(Op::SetText {
                id: 17,
                text: format!("by {}", ["Ada", "Ken"][i % 2]),
            })
            .unwrap();
            c.commit();
            total += start.elapsed();
        }
        eprintln!(
            "cell relayout ({idle} ms idle between frames): {:?} per commit",
            total / n as u32
        );
    }
}

fn input_core() -> Core<FakeEngine> {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Input,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Placeholder("Name".into()),
            },
            style_op(2, &[("padding", StyleValue::Number(6.0))]),
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    c
}

#[test]
fn an_input_takes_its_caret_and_selection_colors_apart() {
    // `caretColor` (or `caret-*`) is the caret's, `selectionColor` the
    // selection highlight's: neither stands in for the other.
    let colors = |classes: &str, style: &[(&str, StyleValue<'_>)]| {
        let mut c = input_core();
        c.apply(class_op(2, classes)).unwrap();
        c.apply(style_op(2, style)).unwrap();
        let batch = c.commit().unwrap();
        batch.items.iter().rev().find_map(|i| match i {
            MountItem::Input { id: 2, config } => {
                Some((config.caret_color, config.selection_color))
            }
            _ => None,
        })
    };
    let (red, blue) = (Color(0xff00_00ff), Color(0x0000_ffff));
    assert_eq!(
        colors(
            "",
            &[
                ("caretColor", StyleValue::Str("red")),
                ("selectionColor", StyleValue::Str("blue"))
            ]
        ),
        Some((Some(red), Some(blue)))
    );
    assert_eq!(colors("caret-[#ff0000]", &[]), Some((Some(red), None)));
    // The style wins over the class.
    assert_eq!(
        colors(
            "caret-[#ff0000]",
            &[("caretColor", StyleValue::Str("blue"))]
        ),
        Some((Some(blue), None))
    );
}

#[test]
fn input_measures_its_placeholder_and_reports_its_content_box() {
    let mut c = input_core();
    let batch = c.commit().unwrap();
    // One line of text (16pt) plus padding, stretched across the root.
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.height.0), Some(28.0));
    assert!(batch.items.iter().any(|i| matches!(i,
        MountItem::Input { id: 2, config } if config.placeholder == "Name" && !config.multiline)));
    assert!(batch.items.iter().any(|i| matches!(i,
        MountItem::InputContent { id: 2, content } if *content == rect(6.0, 6.0, 308.0, 16.0))));
    // No text yet: nothing to send.
    assert!(
        !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::InputValue { .. }))
    );
}

#[test]
fn input_out_of_the_layout_has_no_content_box() {
    // `display: none` around an input leaves it no box, and a platform that
    // does not clip a view's children to it (a browser) would draw its
    // field, placeholder and all, at the content box it had before.
    let mut c = input_core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 3,
                tag: Tag::View,
            },
            Op::Remove {
                parent: ROOT_ID,
                child: 2,
            },
            Op::Insert {
                parent: 3,
                child: 2,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: None,
            },
        ],
    );
    let content_of = |batch: &MountBatch| {
        batch.items.iter().find_map(|i| match i {
            MountItem::InputContent { id: 2, content } => Some(*content),
            _ => None,
        })
    };
    let shown = Some(rect(6.0, 6.0, 308.0, 16.0));
    assert_eq!(content_of(&c.commit().unwrap()), shown);
    let mut toggle = |id, classes, expected: Option<Bounds<Points>>| {
        c.apply(class_op(id, classes)).unwrap();
        assert_eq!(
            content_of(&c.commit().unwrap()),
            expected,
            "{id}: {classes}"
        );
    };
    // Hidden by its parent's class, then by its own.
    toggle(3, "hidden", Some(Bounds::default()));
    toggle(3, "flex flex-col", shown);
    toggle(2, "hidden", Some(Bounds::default()));
    toggle(2, "flex", shown);
}

#[test]
fn inputs_resolve_what_return_does() {
    use crate::{SubmitBehavior as S, mount::InputConfig};
    let config = |multiline, blur_on_submit, submit_behavior| InputConfig {
        multiline,
        blur_on_submit,
        submit_behavior,
        ..InputConfig::default()
    };
    // React Native's defaults: one line submits and unfocuses, several
    // lines take line breaks; `blur_on_submit` false keeps the focus.
    assert_eq!(config(false, true, None).submit(), S::BlurAndSubmit);
    assert_eq!(config(false, false, None).submit(), S::Submit);
    assert_eq!(config(true, true, None).submit(), S::Newline);
    // `submitBehavior` wins; one line never takes line breaks.
    assert_eq!(config(true, true, Some(S::Submit)).submit(), S::Submit);
    assert_eq!(
        config(false, false, Some(S::BlurAndSubmit)).submit(),
        S::BlurAndSubmit
    );
    assert_eq!(
        config(false, true, Some(S::Newline)).submit(),
        S::BlurAndSubmit
    );
}

#[test]
fn inputs_take_their_submit_behavior() {
    let mut c = input_core();
    c.commit().unwrap();
    apply(
        &mut c,
        vec![
            Op::SetProp {
                id: 2,
                prop: Prop::Multiline(true),
            },
            Op::SetProp {
                id: 2,
                prop: Prop::SubmitBehavior(Some(crate::SubmitBehavior::Submit)),
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(|i| matches!(i,
        MountItem::Input { id: 2, config } if config.submit() == crate::SubmitBehavior::Submit)));
}

#[test]
fn input_values_from_js_and_native_edits() {
    let mut c = input_core();
    c.commit();
    // The user types; JS echoes the same text: nothing goes back.
    c.input_changed(2, "ab", 2);
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Value("ab".into()),
    })
    .unwrap();
    assert!(c.commit().is_none());
    // JS transforms the text: it is sent with the edit count it is based on.
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Value("AB".into()),
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(|i| matches!(i,
        MountItem::InputValue { id: 2, text, count: 2 } if text == "AB")));
    // `defaultValue` no longer applies once a value was set.
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::DefaultValue("x".into()),
    })
    .unwrap();
    assert!(c.commit().is_none());
}

/// An input with `style`, in a row with `flex: 1` when `flex`, or alone, in a
/// view its content sizes.
fn hugged_input(style: &[(&str, StyleValue<'_>)], flex: bool) -> Core<FakeEngine> {
    let mut c = core();
    let mut ops = vec![
        Op::Create {
            id: 7,
            tag: Tag::View,
        },
        style_op(7, &[("alignItems", StyleValue::Str("flex-start"))]),
        Op::Create {
            id: 3,
            tag: Tag::View,
        },
        style_op(3, &[("flexDirection", StyleValue::Str("row"))]),
        Op::Create {
            id: 2,
            tag: Tag::Input,
        },
        style_op(2, style),
    ];
    if flex {
        ops.push(style_op(2, &[("flex", StyleValue::Number(1.0))]));
    }
    for (parent, child) in [(3, 2), (7, 3), (ROOT_ID, 7)] {
        ops.push(Op::Insert {
            parent,
            child,
            before: None,
        });
    }
    apply(&mut c, ops);
    c
}

#[test]
fn an_inputs_width_does_not_come_from_its_text() {
    for flex in [false, true] {
        let mut c = hugged_input(&[], flex);
        // Twenty digits at 8pt, whatever it holds.
        let batch = c.commit().unwrap();
        assert_eq!(frame_of(&batch, 2).map(|f| f.size.width.0), Some(160.0));
        c.input_changed(2, "x", 1);
        // Typing does not move it, if its frame is sent at all.
        let width = |batch: Option<MountBatch>| {
            batch
                .and_then(|b| frame_of(&b, 3))
                .map_or(160.0, |f| f.size.width.0)
        };
        assert_eq!(width(c.commit()), 160.0);
        c.input_changed(2, &"x".repeat(30), 2);
        assert_eq!(width(c.commit()), 160.0);
    }
    // A multiline one wraps at that width: 30
    // characters at 8pt in 160pt is two lines.
    let mut c = hugged_input(&[], false);
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(true),
    })
    .unwrap();
    c.commit();
    c.input_changed(2, &"x".repeat(30), 1);
    let batch = c.commit().unwrap();
    assert_eq!(
        frame_of(&batch, 2).map(|f| (f.size.width.0, f.size.height.0)),
        Some((160.0, 32.0))
    );
    // A width of its own stays.
    let batch = hugged_input(&[("width", StyleValue::Number(90.0))], false)
        .commit()
        .unwrap();
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.width.0), Some(90.0));
}

#[test]
fn multiline_inputs_grow_with_their_text() {
    let mut c = input_core();
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(true),
    })
    .unwrap();
    c.commit();
    // 50 characters at 8pt in 308pt: two lines.
    c.input_changed(2, &"x".repeat(50), 1);
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.height.0), Some(44.0));
    // A trailing line break starts an empty line that still takes space.
    c.input_changed(2, "x\n", 2);
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.height.0), Some(28.0));
}

#[test]
fn multiline_inputs_grow_with_what_an_input_method_composes() {
    let mut c = input_core();
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(true),
    })
    .unwrap();
    c.commit();
    // 30 characters at 8pt in 308pt: one line, as the placeholder.
    c.input_changed(2, &"x".repeat(30), 1);
    assert_eq!(c.commit().and_then(|b| frame_of(&b, 2)), None);
    // Composing 20 more wraps the line: the input grows before it commits.
    c.input_composing(2, Some(&"x".repeat(50)));
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.height.0), Some(44.0));
    // Its value is still what was committed.
    let node = &c.nodes[c.key(2).unwrap() as usize];
    assert_eq!(node.input.as_ref().unwrap().value, "x".repeat(30));
    // Cancelled, it goes back to its value's height.
    c.input_composing(2, None);
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 2).map(|f| f.size.height.0), Some(28.0));
    // Committed, it keeps the height the composition gave it.
    c.input_composing(2, Some(&"x".repeat(50)));
    c.commit();
    c.input_changed(2, &"x".repeat(50), 2);
    c.input_composing(2, None);
    let batch = c.commit();
    assert_eq!(batch.and_then(|b| frame_of(&b, 2)), None);
}

#[test]
fn multiline_inputs_measure_long_runs_in_pieces() {
    let mut c = input_core();
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(true),
    })
    .unwrap();
    c.commit();
    let key = c.key(2).unwrap();
    let measured = |c: &Core<FakeEngine>, content: &str| c.input_text(key, content).text;
    // A run without white space as long as minified JSON or Base64 is
    // measured with a line break after every 1024 characters (platform
    // line breakers take quadratic time on one long run)...
    let run = "é".repeat(2500);
    let pieces: Vec<String> = measured(&c, &run).split('\n').map(String::from).collect();
    assert_eq!(
        pieces,
        ["é".repeat(1024), "é".repeat(1024), "é".repeat(452)]
    );
    // ... counted from the last white space, never ending the text with one.
    let words = format!("{} {}", "a".repeat(1500), "b".repeat(1024));
    assert_eq!(
        measured(&c, &words),
        format!(
            "{}\n{} {}",
            "a".repeat(1024),
            "a".repeat(476),
            "b".repeat(1024)
        )
    );
    // Existing breaks are not duplicated, and non-breaking spaces do not
    // let a long unbreakable run evade the limit.
    let ending = format!("{}\n", "a".repeat(1024));
    assert_eq!(measured(&c, &ending), format!("{ending}\u{200b}"));
    let nbsp = "a\u{a0}".repeat(1200);
    assert!(measured(&c, &nbsp).contains('\n'));
    let cjk = "漢".repeat(2500);
    assert_eq!(measured(&c, &cjk), cjk);
    // Text without such runs, and a single line, measure as they are.
    let prose = "lorem ipsum ".repeat(500);
    assert_eq!(measured(&c, &prose), prose);
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(false),
    })
    .unwrap();
    assert_eq!(measured(&c, &run), run);
    // The input itself keeps its value.
    c.apply(Op::SetProp {
        id: 2,
        prop: Prop::Multiline(true),
    })
    .unwrap();
    c.input_changed(2, &run, 1);
    c.commit();
    assert_eq!(
        c.nodes[key as usize]
            .input
            .as_ref()
            .map(|i| i.value.as_str()),
        Some(run.as_str())
    );
}

#[test]
fn commands_reach_created_views_only() {
    let mut c = input_core();
    c.apply(Op::Command {
        id: 2,
        command: crate::Command::Focus,
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert!(matches!(
        batch.items.last(),
        Some(MountItem::Command {
            id: 2,
            command: crate::Command::Focus
        })
    ));
    c.apply(Op::Create {
        id: 3,
        tag: Tag::Input,
    })
    .unwrap();
    c.apply(Op::Command {
        id: 3,
        command: crate::Command::Focus,
    })
    .unwrap();
    assert!(c.commit().is_none());
}

fn insert_items(batch: &MountBatch) -> Vec<(NodeId, NodeId, Option<NodeId>)> {
    batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::Insert {
                parent,
                child,
                before,
            } => Some((*parent, *child, *before)),
            _ => None,
        })
        .collect()
}

#[test]
fn z_index_orders_native_views() {
    let mut c = core();
    let z = |v: f32| style(&[("zIndex", StyleValue::Number(v))]);
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::Create {
                id: 3,
                tag: Tag::View,
            },
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 2,
                style: z(5.0),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
            Op::Insert {
                parent: 1,
                child: 3,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    // 3 (z 0) goes below 2 (z 5) although it comes later in the tree.
    assert_eq!(insert_items(&batch), vec![(1, 2, None), (1, 3, Some(2))]);
    // Raising 3 above 2 moves it to the top.
    apply(
        &mut c,
        vec![Op::SetStyle {
            id: 3,
            style: z(9.0),
            patch: StylePatch::default(),
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(insert_items(&batch), vec![(1, 3, None)]);
    // A new child with the default z index goes below both.
    apply(
        &mut c,
        vec![Op::Insert {
            parent: 1,
            child: 4,
            before: None,
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(insert_items(&batch), vec![(1, 4, Some(2))]);
}

#[test]
fn tracked_tree_order_follows_logical_moves_without_following_stacking() {
    let mut c = core();
    c.set_tree_order_tracking(true);
    let order = |batch: &MountBatch| {
        batch.items.iter().find_map(|item| match item {
            MountItem::TreeOrder(nodes) => Some(nodes.clone()),
            _ => None,
        })
    };
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            Op::Create {
                id: 3,
                tag: Tag::View,
            },
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 2,
                style: style(&[("zIndex", StyleValue::Number(5.0))]),
                patch: StylePatch::default(),
            },
            Op::Insert {
                parent: 2,
                child: 4,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(insert_items(&batch).contains(&(ROOT_ID, 3, Some(2))));
    assert_eq!(order(&batch), Some(vec![ROOT_ID, 2, 4, 3]));
    c.apply(Op::SetStyle {
        id: 3,
        style: style(&[("zIndex", StyleValue::Number(9.0))]),
        patch: StylePatch::default(),
    })
    .unwrap();
    let batch = c.commit().unwrap();
    assert_eq!(insert_items(&batch), vec![(ROOT_ID, 3, None)]);
    assert_eq!(order(&batch), None, "restacking preserves logical order");
    for (op, expected) in [
        (
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: Some(2),
            },
            vec![ROOT_ID, 3, 2, 4],
        ),
        (
            Op::Insert {
                parent: 3,
                child: 4,
                before: None,
            },
            vec![ROOT_ID, 3, 4, 2],
        ),
        (
            Op::Remove {
                parent: ROOT_ID,
                child: 3,
            },
            vec![ROOT_ID, 2],
        ),
    ] {
        c.apply(op).unwrap();
        assert_eq!(order(&c.commit().unwrap()), Some(expected));
    }
    assert!(c.commit().is_none());
    c.set_tree_order_tracking(false);
    c.apply(Op::Insert {
        parent: ROOT_ID,
        child: 3,
        before: None,
    })
    .unwrap();
    assert_eq!(order(&c.commit().unwrap()), None);
}

#[test]
fn layout_events_carry_frames_and_late_listeners_get_one() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            style_op(2, &[("height", StyleValue::Number(40.0))]),
            Op::Listen {
                id: 2,
                event: EventKind::Layout,
                enabled: true,
            },
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
        ],
    );
    c.commit().unwrap();
    let events = js_events(&mut c);
    assert_eq!(
        events,
        vec![(
            2,
            EventKind::Layout,
            EventPayload::Layout(rect(0.0, 0.0, 320.0, 40.0))
        )]
    );
    // Unchanged frames report nothing; a listener added later learns the
    // current frame.
    apply(
        &mut c,
        vec![
            Op::Listen {
                id: 2,
                event: EventKind::Layout,
                enabled: false,
            },
            Op::Listen {
                id: 2,
                event: EventKind::Layout,
                enabled: true,
            },
        ],
    );
    c.commit();
    let events = js_events(&mut c);
    assert_eq!(events.len(), 1);
}

