/// A label that follows app state goes alone, not with all the view's
/// props; any other change (or the first props) sends them all.
#[test]
fn a_changing_label_is_sent_alone() {
    use crate::props::AccessibilityProp;
    let label = |v: &str| Op::SetProp {
        id: 2,
        prop: Prop::Accessibility(AccessibilityProp::Label(Some(v.into()))),
    };
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::View,
            },
            label("0 items"),
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(|i| matches!(i, MountItem::ViewProps { id: 2, props } if props.accessibility.label.as_deref() == Some("0 items"))));
    apply(&mut c, vec![label("1 item")]);
    let batch = c.commit().unwrap();
    assert_eq!(batch.items.len(), 1, "{:?}", batch.items);
    assert!(
        matches!(&batch.items[0], MountItem::AccessibilityLabel { id: 2, label: Some(l) } if &**l == "1 item")
    );
    // With another prop in the same commit, everything goes once.
    apply(
        &mut c,
        vec![
            label("2 items"),
            Op::SetProp {
                id: 2,
                prop: Prop::TestId(Some("counter".into())),
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(batch.items.len(), 1, "{:?}", batch.items);
    assert!(
        matches!(&batch.items[0], MountItem::ViewProps { id: 2, props } if props.accessibility.label.as_deref() == Some("2 items"))
    );
}

/// `nativeID` names any view for the embedding app (a scroll view it
/// watches, `watchScroll`): it reaches the platforms apart from `testID`.
#[test]
fn native_id_reaches_the_platform() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Scroll,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::NativeId(Some("page".into())),
            },
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert!(batch.items.iter().any(|i| matches!(i, MountItem::ViewProps { id: 2, props } if props.native_id.as_deref() == Some("page") && props.test_id.is_none())));
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::NativeId(None),
        }],
    );
    let batch = c.commit().unwrap();
    assert!(
        batch.items.iter().any(
            |i| matches!(i, MountItem::ViewProps { id: 2, props } if props.native_id.is_none())
        )
    );
}

/// The relations of one view's last `ViewProps` in `batch`: its active
/// descendant and what it controls.
fn relations_in(batch: &MountBatch, id: NodeId) -> Option<(Option<NodeId>, Option<NodeId>)> {
    batch.items.iter().rev().find_map(|i| match i {
        MountItem::ViewProps { id: at, props } if *at == id => Some((
            props.accessibility.active_descendant,
            props.accessibility.controls,
        )),
        _ => None,
    })
}

/// `accessibilityActiveDescendant` and `accessibilityControls` name other
/// views: the platform gets their ids, as the views named change, come
/// after the one naming them or go.
#[test]
fn accessibility_relations_name_other_views() {
    use crate::element::ElementTarget;
    let mut c = core();
    let view = |id| Op::Create { id, tag: Tag::View };
    let insert = |parent, child| Op::Insert {
        parent,
        child,
        before: None,
    };
    let active = |target: Option<NodeId>| Op::SetProp {
        id: 2,
        prop: Prop::Accessibility(AccessibilityProp::ActiveDescendant(
            target.map(ElementTarget::of_node),
        )),
    };
    // A field naming its list and the list's first option.
    apply(
        &mut c,
        vec![
            view(2),
            view(4),
            view(6),
            view(8),
            insert(1, 2),
            insert(1, 4),
            insert(4, 6),
            insert(4, 8),
            active(Some(6)),
            Op::SetProp {
                id: 2,
                prop: Prop::Accessibility(AccessibilityProp::Controls(Some(
                    ElementTarget::of_node(4),
                ))),
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), Some((Some(6), Some(4))));
    // The highlight moves: only the field's props go again.
    apply(&mut c, vec![active(Some(8))]);
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), Some((Some(8), Some(4))));
    // Something else changes: the field's props do not go again.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 6,
            prop: Prop::TestId(Some("first".into())),
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), None);
    // The option named goes: the field names none.
    apply(
        &mut c,
        vec![
            Op::Remove {
                parent: 4,
                child: 8,
            },
            Op::Release { id: 8 },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), Some((None, Some(4))));
    // A view named before it is made is named once it is.
    apply(&mut c, vec![active(Some(10))]);
    assert_eq!(c.commit().and_then(|b| relations_in(&b, 2)), None);
    apply(&mut c, vec![view(10), insert(4, 10)]);
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), Some((Some(10), Some(4))));
    // Cleared.
    apply(
        &mut c,
        vec![
            active(None),
            Op::SetProp {
                id: 2,
                prop: Prop::Accessibility(AccessibilityProp::Controls(None)),
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(relations_in(&batch, 2), Some((None, None)));
    assert!(c.relators.is_empty());
}

#[test]
fn screens_fill_their_stack_below_the_header() {
    let mut c = core();
    c.set_safe_area(crate::EdgeInsets {
        top: px(20.0),
        ..Default::default()
    });
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Stack,
            },
            style_op(2, &[("flex", StyleValue::Number(1.0))]),
            Op::Create {
                id: 3,
                tag: Tag::Screen,
            },
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            style_op(4, &[("flex", StyleValue::Number(1.0))]),
            Op::Insert {
                parent: 3,
                child: 4,
                before: None,
            },
            Op::Insert {
                parent: 2,
                child: 3,
                before: None,
            },
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    // The screen fills the stack; its content starts below the status bar
    // and the 44pt bar.
    assert_eq!(frame_of(&batch, 3), Some(rect(0.0, 0.0, 320.0, 480.0)));
    assert_eq!(frame_of(&batch, 4), Some(rect(0.0, 64.0, 320.0, 416.0)));
    assert!(batch.items.iter().any(
        |i| matches!(i, MountItem::ScreenConfig { id: 3, config } if config.header_height == px(64.0))
    ));
    // The header the platform measured replaces the estimate (Catalyst
    // can show its bar in the window's title bar).
    c.set_screen_header(3, Some(px(52.0)));
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 4), Some(rect(0.0, 52.0, 320.0, 428.0)));
    assert!(batch.items.iter().any(
        |i| matches!(i, MountItem::ScreenConfig { id: 3, config } if config.header_height == px(52.0))
    ));
    // Without a header, the content starts at the top.
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 3,
            prop: Prop::Screen(crate::ScreenProp::HeaderVisible(false)),
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 4), Some(rect(0.0, 0.0, 320.0, 480.0)));
}

/// Without a native header, a screen's `header` slot is as wide as the
/// screen whatever it holds: a long one-line title shrinks instead of
/// pushing the header, and the button after it, past the window's edge.
#[test]
fn a_drawn_header_is_as_wide_as_the_screen() {
    let mut c = core();
    c.set_header_heights(crate::NO_NATIVE_HEADER.0, crate::NO_NATIVE_HEADER.1);
    let square = |id| {
        style_op(
            id,
            &[
                ("width", StyleValue::Number(44.0)),
                ("height", StyleValue::Number(44.0)),
                ("flexShrink", StyleValue::Number(0.0)),
            ],
        )
    };
    let insert = |parent, child| Op::Insert {
        parent,
        child,
        before: None,
    };
    let mut ops = vec![
        Op::Create {
            id: 2,
            tag: Tag::Stack,
        },
        style_op(2, &[("flex", StyleValue::Number(1.0))]),
        Op::Create {
            id: 3,
            tag: Tag::Screen,
        },
        Op::Create {
            id: 4,
            tag: Tag::HeaderItem,
        },
        Op::SetProp {
            id: 4,
            prop: Prop::HeaderSlot(crate::HeaderSlot::Header),
        },
        Op::Create {
            id: 6,
            tag: Tag::View,
        },
        style_op(6, &[("flexDirection", StyleValue::Str("row"))]),
        Op::Create {
            id: 8,
            tag: Tag::View,
        },
        square(8),
        Op::Create {
            id: 10,
            tag: Tag::View,
        },
        style_op(
            10,
            &[
                ("flex", StyleValue::Number(1.0)),
                ("minWidth", StyleValue::Number(0.0)),
            ],
        ),
        Op::Create {
            id: 12,
            tag: Tag::Text,
        },
        style_op(12, &[("numberOfLines", StyleValue::Number(1.0))]),
        Op::CreateText {
            id: 13,
            text: "a title far too long to fit on one line of the header".repeat(2),
        },
        Op::Create {
            id: 14,
            tag: Tag::View,
        },
        square(14),
        Op::Create {
            id: 16,
            tag: Tag::View,
        },
        style_op(16, &[("flex", StyleValue::Number(1.0))]),
    ];
    ops.extend([
        insert(12, 13),
        insert(10, 12),
        insert(6, 8),
        insert(6, 10),
        insert(6, 14),
        insert(4, 6),
        insert(3, 4),
        insert(3, 16),
        insert(2, 3),
        insert(ROOT_ID, 2),
    ]);
    apply(&mut c, ops);
    let mut frames = std::collections::HashMap::new();
    for width in [320.0, 360.0, 600.0] {
        c.set_viewport(size_pt(width, 480.0));
        let batch = c.commit().unwrap();
        for item in &batch.items {
            if let MountItem::Frame { id, frame } = item {
                frames.insert(*id, *frame);
            }
        }
        let header = frames[&4];
        assert_eq!(header.size.width, px(width), "the header at {width}");
        let right = frames[&14];
        assert_eq!(
            right.origin.x + right.size.width,
            px(width),
            "the button after the title at {width}"
        );
        assert_eq!(frames[&10].size.width, px(width - 88.0));
    }
}

#[test]
fn a_screen_keeps_the_bottom_bar_unless_it_says_otherwise() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Stack,
            },
            style_op(2, &[("flex", StyleValue::Number(1.0))]),
            Op::Create {
                id: 3,
                tag: Tag::Screen,
            },
            Op::Insert {
                parent: 2,
                child: 3,
                before: None,
            },
            Op::Insert {
                parent: 1,
                child: 2,
                before: None,
            },
        ],
    );
    // `hidesBottomBarWhenPushed` is off unless the page asks for it: the
    // platform looks the flag up on the screen it shows.
    let batch = c.commit().unwrap();
    assert!(
        batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::ScreenConfig { id: 3, config }
            if !config.hides_bottom_bar_when_pushed))
    );
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 3,
            prop: Prop::Screen(crate::ScreenProp::HidesBottomBarWhenPushed(true)),
        }],
    );
    let batch = c.commit().unwrap();
    assert!(
        batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::ScreenConfig { id: 3, config }
            if config.hides_bottom_bar_when_pushed))
    );
}

