#[test]
fn an_input_that_edits_shows_its_focus_whatever_gave_it() {
    use crate::{platform::InputModality, tailwind::state::FOCUSED};
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Input,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
            Op::Create {
                id: 4,
                tag: Tag::Input,
            },
            Op::SetProp {
                id: 4,
                prop: Prop::Readonly(true),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 4,
                before: None,
            },
        ],
    );
    c.commit();
    c.set_input_modality(InputModality::Pointer);
    c.set_states(2, FOCUSED);
    c.commit();
    assert!(focus_visible(&c, 2), "a tap into a field shows its focus");
    // A read-only one takes no typing: a tap gives it the focus unseen.
    c.set_states(4, FOCUSED);
    c.set_states(2, 0);
    c.commit();
    assert!(!focus_visible(&c, 4) && !focus_visible(&c, 2));
}

#[test]
fn the_input_modality_alone_sends_nothing() {
    use crate::platform::InputModality;
    // No focus: a key or a press changes no view.
    let mut c = core();
    views(&mut c, &[(2, ROOT_ID, "focus-visible:opacity-50")]);
    c.commit();
    c.set_input_modality(InputModality::Keyboard);
    assert!(c.commit().is_none_or(|b| b.items.is_empty()));
    c.set_input_modality(InputModality::Pointer);
    assert!(c.commit().is_none_or(|b| b.items.is_empty()));
}

#[test]
fn a_focus_visible_style_and_group_follow_the_shown_focus() {
    use crate::{platform::InputModality, tailwind::state::FOCUSED};
    let mut c = core();
    views(
        &mut c,
        &[
            (2, ROOT_ID, "group opacity-50"),
            (4, 2, "opacity-50 group-focus-visible:opacity-100"),
        ],
    );
    apply(
        &mut c,
        vec![Op::SetProp {
            id: 2,
            prop: Prop::FocusVisibleStyle(patch(&[("opacity", crate::StyleValue::Number(0.8))])),
        }],
    );
    c.commit();
    c.set_input_modality(InputModality::Pointer);
    c.set_states(2, FOCUSED);
    let batch = c.commit();
    assert!(batch.as_ref().is_none_or(|b| view_style_of(b, 2).is_none()));
    assert!(batch.as_ref().is_none_or(|b| view_style_of(b, 4).is_none()));
    c.set_input_modality(InputModality::Keyboard);
    let batch = c.commit().unwrap();
    assert_eq!(view_style_of(&batch, 2).unwrap().opacity, 0.8);
    assert_eq!(view_style_of(&batch, 4).unwrap().opacity, 1.0);
}

#[test]
fn a_focus_reported_untracked_survives_a_tracking_change() {
    use crate::tailwind::state::{FOCUSED, HOVERED};
    // The platform reports the focus whatever is tracked, and keeps it
    // when the tracking changes: so does the core.
    let mut c = core();
    views(
        &mut c,
        &[
            (2, ROOT_ID, "opacity-50 focus-within:opacity-100"),
            (4, 2, "bg-white"),
        ],
    );
    c.commit();
    c.set_states(4, FOCUSED);
    c.commit();
    apply(&mut c, vec![class_op(4, "bg-white hover:bg-zinc-200")]);
    c.commit();
    assert!(c.has_focus_within(2));
    c.set_states(4, FOCUSED | HOVERED);
    apply(&mut c, vec![class_op(4, "bg-white")]);
    c.commit();
    assert!(c.has_focus_within(2) && c.has_focus_within(4));
}

#[test]
fn input_accessories_are_found_by_native_id() {
    let mut c = core();
    let accessory = |batch: &MountBatch| {
        batch.items.iter().rev().find_map(|i| match i {
            MountItem::Input { id: 2, config } => Some(config.accessory),
            _ => None,
        })
    };
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Input,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::InputAccessoryViewId(Some("bar".into())),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(accessory(&batch), Some(None));
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 3,
                tag: Tag::InputAccessory,
            },
            Op::SetProp {
                id: 3,
                prop: Prop::NativeId(Some("bar".into())),
            },
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            Op::SetStyle {
                id: 4,
                style: style(&[("height", StyleValue::Number(44.0))]),
                patch: Default::default(),
            },
            Op::Insert {
                parent: 3,
                child: 4,
                before: None,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 3,
                before: None,
            },
        ],
    );
    let batch = c.commit().unwrap();
    assert_eq!(accessory(&batch), Some(Some(3)));
    // As wide as the window, as tall as its content.
    let frame = frame_of(&batch, 3).unwrap();
    assert_eq!((frame.size.width.0, frame.size.height.0), (320.0, 44.0));
    apply(
        &mut c,
        vec![Op::Remove {
            parent: ROOT_ID,
            child: 3,
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(accessory(&batch), Some(None));
}

#[test]
fn inputs_report_their_content_size() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Input,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Multiline(true),
            },
            Op::SetStyle {
                id: 2,
                style: style(&[("width", StyleValue::Number(100.0))]),
                patch: Default::default(),
            },
            Op::Listen {
                id: 2,
                event: EventKind::ContentSizeChange,
                enabled: true,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let sizes = |c: &mut Core<FakeEngine>| {
        js_events(c)
            .into_iter()
            .filter(|(id, kind, _)| *id == 2 && *kind == EventKind::ContentSizeChange)
            .count()
    };
    c.commit().unwrap();
    assert_eq!(sizes(&mut c), 1);
    // Typing a long text wraps it: taller.
    c.input_changed(2, &"x".repeat(80), 1);
    c.commit();
    assert_eq!(sizes(&mut c), 1);
    // The same text again: no event.
    c.input_changed(2, &"x".repeat(80), 2);
    c.commit();
    assert_eq!(sizes(&mut c), 0);
}

#[test]
fn fixed_size_inputs_report_their_content_size() {
    let mut c = core();
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Input,
            },
            Op::SetProp {
                id: 2,
                prop: Prop::Placeholder("A much longer placeholder".into()),
            },
            Op::SetStyle {
                id: 2,
                style: style(&[
                    ("width", StyleValue::Number(200.0)),
                    ("height", StyleValue::Number(40.0)),
                ]),
                patch: Default::default(),
            },
            Op::Listen {
                id: 2,
                event: EventKind::ContentSizeChange,
                enabled: true,
            },
            Op::Insert {
                parent: ROOT_ID,
                child: 2,
                before: None,
            },
        ],
    );
    let sizes = |c: &mut Core<FakeEngine>| {
        js_events(c)
            .into_iter()
            .filter(|(id, kind, _)| *id == 2 && *kind == EventKind::ContentSizeChange)
            .map(|(_, _, p)| p)
            .collect::<Vec<_>>()
    };
    let size = |width: f64, height: f64| {
        vec![EventPayload::Map(vec![
            ("width", PayloadValue::Number(width)),
            ("height", PayloadValue::Number(height)),
        ])]
    };
    let frame = |batch: &MountBatch| {
        batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Frame { id: 2, .. }))
    };
    // Sized by its placeholder, an empty input reports an empty line (the
    // fake engine gives its zero-width space a width).
    let batch = c.commit().unwrap();
    assert!(frame(&batch));
    assert_eq!(sizes(&mut c), size(8.0, 16.0));
    // Its frame stays as the user types; its text's size is reported.
    for (count, (text, width)) in [("ab", 16.0), ("abc", 24.0)].into_iter().enumerate() {
        c.input_changed(2, text, count as u32 + 1);
        assert!(c.commit().is_none_or(|b| !frame(&b)));
        assert_eq!(sizes(&mut c), size(width, 16.0), "{text:?}");
    }
    // A value that reads as the placeholder: its own size.
    c.input_changed(2, "A much longer placeholder", 3);
    c.commit();
    assert_eq!(sizes(&mut c), size(200.0, 16.0));
    c.input_changed(2, "", 4);
    c.commit();
    assert_eq!(sizes(&mut c), size(8.0, 16.0));
    // Nothing changed: nothing reported, nothing measured or mounted.
    c.input_changed(2, "", 5);
    assert!(c.commit().is_none());
    assert_eq!(sizes(&mut c), Vec::new());
}

#[test]
fn text_shrinks_to_fit_its_lines() {
    let mut c = Core::new(crate::text::ApproxTextEngine, size_pt(320.0, 480.0));
    let ops = vec![
        Op::Create {
            id: 2,
            tag: Tag::Text,
        },
        Op::SetStyle {
            id: 2,
            style: style(&[
                ("width", StyleValue::Number(60.0)),
                ("fontSize", StyleValue::Number(20.0)),
                ("numberOfLines", StyleValue::Number(1.0)),
            ]),
            patch: Default::default(),
        },
        Op::SetProp {
            id: 2,
            prop: Prop::AdjustsFontSizeToFit(true),
        },
        Op::CreateText {
            id: 3,
            text: "Hello world".into(),
        },
        Op::Insert {
            parent: 2,
            child: 3,
            before: None,
        },
        Op::Insert {
            parent: ROOT_ID,
            child: 2,
            before: None,
        },
    ];
    for op in ops {
        c.apply(op).unwrap();
    }
    let batch = c.commit().unwrap();
    let size = batch
        .items
        .iter()
        .find_map(|i| match i {
            MountItem::Text { id: 2, text, .. } => Some(text.spans[0].style.font_size.0),
            _ => None,
        })
        .unwrap();
    // 11 characters at 0.55 em in 60pt: at most ~9.9pt.
    assert!(size < 10.0 && size > 9.0, "{size}");
}

#[test]
fn styles_clamp_cut_and_select_texts_and_say_which_views_take_touches() {
    let mut c = Core::new(crate::text::ApproxTextEngine, size_pt(320.0, 480.0));
    let insert = |parent, child| Op::Insert {
        parent,
        child,
        before: None,
    };
    let ops = vec![
        Op::Create {
            id: 2,
            tag: Tag::Text,
        },
        Op::SetStyle {
            id: 2,
            style: style(&[
                ("numberOfLines", StyleValue::Number(2.0)),
                ("textOverflow", StyleValue::Str("ellipsis-middle")),
                ("userSelect", StyleValue::Str("text")),
            ]),
            patch: Default::default(),
        },
        Op::CreateText {
            id: 3,
            text: "Hello world".into(),
        },
        insert(2, 3),
        insert(ROOT_ID, 2),
        // React Native's `box-none`: the view takes no touches, the ones in
        // it do (it is not inherited).
        Op::Create {
            id: 4,
            tag: Tag::View,
        },
        Op::SetStyle {
            id: 4,
            style: style(&[("pointerEvents", StyleValue::Str("box-none"))]),
            patch: Default::default(),
        },
        Op::Create {
            id: 6,
            tag: Tag::View,
        },
        insert(4, 6),
        insert(ROOT_ID, 4),
    ];
    for op in ops {
        c.apply(op).unwrap();
    }
    let batch = c.commit().unwrap();
    let text = batch
        .items
        .iter()
        .find_map(|i| match i {
            MountItem::Text { id: 2, text, .. } => Some(text),
            _ => None,
        })
        .unwrap();
    assert_eq!(text.max_lines, 2);
    assert_eq!(text.ellipsize, crate::EllipsizeMode::Middle);
    assert_eq!(text.selectable, Some(true));
    let pointer = |id| {
        batch.items.iter().find_map(|i| match i {
            MountItem::ViewProps { id: i, props } if *i == id => Some(props.pointer_events),
            _ => None,
        })
    };
    assert_eq!(pointer(4), Some(crate::PointerEvents::BoxNone));
    assert_eq!(pointer(6), None);
}

#[test]
fn texts_inside_attachments_take_the_color_of_the_text_around() {
    // `<Text style={{ color }}>a <Text>b <View><Text>chip</Text></View></Text></Text>`:
    // the chip's text is the paragraph's color (CSS `color` inherits into
    // an inline block), its font size its own, and it follows a change.
    let mut c = core();
    let raw = |id, text: &str| Op::CreateText {
        id,
        text: text.into(),
    };
    let insert = |parent, child| Op::Insert {
        parent,
        child,
        before: None,
    };
    let text = |id| Op::Create { id, tag: Tag::Text };
    apply(
        &mut c,
        vec![
            text(2),
            style_op(
                2,
                &[
                    ("color", StyleValue::Str("#ff0000")),
                    ("fontSize", StyleValue::Number(20.0)),
                ],
            ),
            raw(3, "a "),
            text(4),
            raw(5, "b "),
            Op::Create {
                id: 6,
                tag: Tag::View,
            },
            text(7),
            raw(8, "chip"),
            // A second chip whose text sets its own color.
            Op::Create {
                id: 9,
                tag: Tag::View,
            },
            text(10),
            style_op(10, &[("color", StyleValue::Str("#0000ff"))]),
            raw(11, "own"),
            insert(7, 8),
            insert(6, 7),
            insert(10, 11),
            insert(9, 10),
            insert(4, 5),
            insert(4, 6),
            insert(4, 9),
            insert(2, 3),
            insert(2, 4),
            insert(ROOT_ID, 2),
        ],
    );
    let style_of = |batch: &MountBatch, id| {
        batch.items.iter().find_map(|i| match i {
            MountItem::Text { id: i, text, .. } if *i == id => Some(text.spans[0].style),
            _ => None,
        })
    };
    let (red, green, blue) = (Color(0xff00_00ff), Color(0x00ff_00ff), Color(0x0000_ffff));
    let batch = c.commit().unwrap();
    let chip = style_of(&batch, 7).expect("the chip's text");
    assert_eq!(chip.color, red);
    assert_eq!(chip.font_size, ResolvedTextStyle::default().font_size);
    assert_eq!(style_of(&batch, 10).map(|s| s.color), Some(blue));
    // The paragraph's color changes: the chip's text follows.
    c.apply(style_op(2, &[("color", StyleValue::Str("#00ff00"))]))
        .unwrap();
    let batch = c.commit().unwrap();
    assert_eq!(style_of(&batch, 7).map(|s| s.color), Some(green));
    // A span's color is nearer.
    c.apply(style_op(4, &[("color", StyleValue::Str("#ffff00"))]))
        .unwrap();
    let batch = c.commit().unwrap();
    assert_eq!(
        style_of(&batch, 7).map(|s| s.color),
        Some(Color(0xffff_00ff))
    );
    // The one with a color of its own keeps it (and is not sent again).
    assert_ne!(
        style_of(&batch, 10).map(|s| s.color),
        Some(Color(0xffff_00ff))
    );
}

#[test]
fn views_inside_text_are_attachments() {
    let mut c = core();
    let raw = |id, text: &str| Op::CreateText {
        id,
        text: text.into(),
    };
    let insert = |parent, child| Op::Insert {
        parent,
        child,
        before: None,
    };
    apply(
        &mut c,
        vec![
            Op::Create {
                id: 2,
                tag: Tag::Text,
            },
            raw(3, "ab"),
            Op::Create {
                id: 4,
                tag: Tag::View,
            },
            style_op(
                4,
                &[
                    ("width", StyleValue::Number(20.0)),
                    ("height", StyleValue::Number(10.0)),
                    ("padding", StyleValue::Number(2.0)),
                ],
            ),
            Op::Create {
                id: 5,
                tag: Tag::View,
            },
            style_op(5, &[("height", StyleValue::Number(3.0))]),
            insert(4, 5),
            // A span holding an image (inside a span still attaches to the
            // block).
            Op::Create {
                id: 6,
                tag: Tag::Text,
            },
            raw(7, "cd"),
            Op::Create {
                id: 8,
                tag: Tag::Image,
            },
            style_op(
                8,
                &[
                    ("width", StyleValue::Number(12.0)),
                    ("height", StyleValue::Number(12.0)),
                ],
            ),
            insert(6, 7),
            insert(6, 8),
            insert(2, 3),
            insert(2, 4),
            insert(2, 6),
            style_op(2, &[("padding", StyleValue::Number(5.0))]),
            insert(ROOT_ID, 2),
        ],
    );
    let batch = c.commit().unwrap();
    let text = batch
        .items
        .iter()
        .find_map(|i| match i {
            MountItem::Text { id: 2, text, .. } => Some(text.clone()),
            _ => None,
        })
        .unwrap();
    assert_eq!(text.text, "ab\u{FFFC}cd\u{FFFC}");
    assert_eq!(
        text.attachments,
        vec![
            crate::TextAttachment {
                index: 2,
                width: Points(20.0),
                height: Points(10.0),
            },
            crate::TextAttachment {
                index: 5,
                width: Points(12.0),
                height: Points(12.0),
            },
        ]
    );
    // Their views go inside the text view, on their placeholders.
    let inserts: Vec<_> = batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::Insert {
                parent: 2, child, ..
            } => Some(*child),
            _ => None,
        })
        .collect();
    assert_eq!(inserts, vec![4, 8]);
    assert_eq!(
        frame_of(&batch, 4),
        Some(rect(5.0 + 16.0, 5.0 + 2.0, 20.0, 10.0))
    );
    assert_eq!(frame_of(&batch, 8).map(|f| f.origin.x.0), Some(5.0 + 40.0));
    // The attachment's own subtree is laid out inside it.
    assert_eq!(frame_of(&batch, 5), Some(rect(2.0, 2.0, 16.0, 3.0)));

    // Growing an attachment builds the text again.
    apply(
        &mut c,
        vec![style_op(
            4,
            &[
                ("width", StyleValue::Number(30.0)),
                ("height", StyleValue::Number(10.0)),
            ],
        )],
    );
    let batch = c.commit().unwrap();
    let text = batch
        .items
        .iter()
        .find_map(|i| match i {
            MountItem::Text { id: 2, text, .. } => Some(text.clone()),
            _ => None,
        })
        .unwrap();
    assert_eq!(text.attachments[0].width, Points(30.0));
    assert_eq!(frame_of(&batch, 4).map(|f| f.size.width.0), Some(30.0));

    // `verticalAlign` builds the text again: the engine places it.
    let align_of = |c: &mut Core<FakeEngine>, align: &str| {
        apply(
            c,
            vec![style_op(4, &[("verticalAlign", StyleValue::Str(align))])],
        );
        let batch = c.commit()?;
        if !batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Text { id: 2, .. }))
        {
            return None;
        }
        let layout = c.nodes[c.key(2).unwrap() as usize].layout.unwrap();
        let cx = c.text_cx(layout);
        Some(cx.alignments.get(cx.text.attachments[0].index))
    };
    assert_eq!(
        align_of(&mut c, "text-top"),
        Some(crate::VerticalAlign::TextTop)
    );
    assert_eq!(
        align_of(&mut c, "middle"),
        Some(crate::VerticalAlign::Middle)
    );
    // Unchanged: nothing to build.
    assert_eq!(align_of(&mut c, "middle"), None);
    assert_eq!(
        align_of(&mut c, "baseline"),
        Some(crate::VerticalAlign::Baseline)
    );

    // Taken out of the text: its view leaves the text view.
    apply(
        &mut c,
        vec![Op::Remove {
            parent: 2,
            child: 4,
        }],
    );
    let batch = c.commit().unwrap();
    assert!(
        batch
            .items
            .iter()
            .any(|i| matches!(i, MountItem::Remove { id: 4 }))
    );
    let text = batch
        .items
        .iter()
        .find_map(|i| match i {
            MountItem::Text { id: 2, text, .. } => Some(text.clone()),
            _ => None,
        })
        .unwrap();
    assert_eq!(text.text, "abcd\u{FFFC}");
    assert_eq!(frame_of(&batch, 8).map(|f| f.origin.x.0), Some(5.0 + 32.0));
}

#[test]
fn node_quota_and_dense_ids() {
    let mut c = core();
    c.set_max_nodes(3);
    // The root is one node.
    for id in 2..4 {
        c.apply(Op::Create { id, tag: Tag::View }).unwrap();
    }
    assert!(matches!(
        c.apply(Op::Create {
            id: 4,
            tag: Tag::View
        }),
        Err(ApplyError::TooManyNodes(3))
    ));
    let mut c = core();
    c.set_max_nodes(1000);
    // An id that would make the id table enormous.
    let err = c
        .apply(Op::Create {
            id: 4_000_000_000,
            tag: Tag::View,
        })
        .unwrap_err();
    assert!(matches!(err, ApplyError::IdOutOfRange(_)) && err.is_fatal());
}

#[test]
fn the_id_table_follows_the_nodes_alive_not_every_id_made() {
    let mut c = core();
    // A stream of short-lived nodes with ever higher ids, as an app that
    // re-renders for hours makes them.
    let mut last = None;
    for id in (2..2_000_000).step_by(2) {
        c.apply(Op::Create { id, tag: Tag::View }).unwrap();
        if let Some(old) = last.replace(id) {
            c.apply(Op::Release { id: old }).unwrap();
        }
        if id % 20_000 == 0 {
            c.commit();
        }
    }
    c.commit();
    assert!(
        c.slots.pages() <= 2,
        "{} pages for {} nodes",
        c.slots.pages(),
        c.slots.len()
    );
    // The newest node and the root are still known.
    assert!(c.key(1_999_998).is_ok());
    assert!(c.key(ROOT_ID).is_ok());
}

#[test]
fn web_views_fail_at_once_where_the_platform_shows_none() {
    let made = |web_views: bool| {
        let mut c = core();
        c.set_environment(crate::element::Environment {
            web_views,
            ..Default::default()
        });
        apply(
            &mut c,
            vec![
                Op::Create {
                    id: 2,
                    tag: Tag::WebView,
                },
                Op::Create {
                    id: 4,
                    tag: Tag::View,
                },
                Op::Insert {
                    parent: ROOT_ID,
                    child: 2,
                    before: None,
                },
            ],
        );
        c.commit();
        js_events(&mut c)
    };
    // Where web views show, nothing to report.
    assert_eq!(made(true), []);
    let events = made(false);
    let [(2, EventKind::Error, EventPayload::Map(fields))] = &events[..] else {
        panic!("expected the web view's error: {events:?}");
    };
    assert!(fields.contains(&(
        "code",
        crate::PayloadValue::Str("ERR_FEATURE_UNAVAILABLE_ON_PLATFORM".into())
    )));
}

#[test]
fn refused_urls_fail_and_send_nothing() {
    let mut c = core();
    c.set_access(Arc::new(crate::access::Access {
        declared: crate::access::Capabilities::from_json(
            &serde_json::json!({ "network": { "hosts": ["cdn.example.com"] } }),
        )
        .unwrap(),
        granted: None,
    }));
    let image = |id, uri: &str| {
        vec![
            Op::Create {
                id,
                tag: Tag::Image,
            },
            Op::Listen {
                id,
                event: EventKind::Error,
                enabled: true,
            },
            Op::SetProp {
                id,
                prop: Prop::Source(Some(ImageSource {
                    uri: uri.into(),
                    size: None,
                    scales: ImageScales::NONE,
                    data: None,
                })),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: id,
                before: None,
            },
        ]
    };
    let mut ops = image(2, "https://cdn.example.com/a.png");
    ops.extend(image(3, "https://tracker.io/pixel.gif"));
    ops.push(Op::Command {
        id: ROOT_ID,
        command: Command::StatusBar(Default::default()),
    });
    apply(&mut c, ops);
    let batch = c.commit().unwrap();
    let sources: Vec<_> = batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::Image { id, source, .. } => {
                Some((*id, source.as_ref().map(|s| s.uri.to_string())))
            }
            _ => None,
        })
        .collect();
    // The refused image loads nothing.
    assert_eq!(
        sources,
        [
            (2, Some("https://cdn.example.com/a.png".to_owned())),
            (3, None)
        ]
    );
    // (The tokens `core()` set go to the platform as ever.)
    assert!(!batch.items.iter().any(|i| matches!(
        i,
        MountItem::Command { command, .. } if !matches!(command, Command::Tokens(_))
    )));
    let events = js_events(&mut c);
    let [(3, EventKind::Error, EventPayload::Map(fields))] = &events[..] else {
        panic!("expected the refused image's error: {events:?}");
    };
    let field = |key| fields.iter().find(|(k, _)| *k == key).map(|(_, v)| v);
    assert!(
        matches!(field("message"), Some(crate::PayloadValue::Str(m)) if m.contains("`tracker.io`"))
    );
    assert_eq!(
        field("code"),
        Some(&crate::PayloadValue::Str("ERR_ACCESS_DENIED".into()))
    );
}

/// An image or a video loads the URL the check granted, as WHATWG's parser
/// reads it: `//` takes the base's scheme, dot segments are resolved, and a
/// source naming a host the app is not granted loads nothing.
#[test]
fn media_sources_load_the_url_the_check_granted() {
    let mut c = core();
    c.set_access(Arc::new(crate::access::Access {
        declared: crate::access::Capabilities::from_json(
            &serde_json::json!({ "network": { "hosts": ["docs.example.com"] } }),
        )
        .unwrap(),
        granted: None,
    }));
    c.set_base_url(Some("https://app.example/index.html".into()));
    let image = |id, uri: &str| {
        vec![
            Op::Create {
                id,
                tag: Tag::Image,
            },
            Op::SetProp {
                id,
                prop: Prop::Source(Some(ImageSource {
                    uri: uri.into(),
                    size: None,
                    scales: ImageScales::NONE,
                    data: None,
                })),
            },
            Op::Insert {
                parent: ROOT_ID,
                child: id,
                before: None,
            },
        ]
    };
    let mut ops = image(2, "//docs.example.com/a/../x.png");
    ops.extend(image(4, "//bank.example/x.png"));
    ops.extend(image(6, "https:\\\\bank.example\\x.png"));
    ops.extend(image(8, "asset:/own.png"));
    ops.extend([
        Op::Create {
            id: 10,
            tag: Tag::Video,
        },
        Op::SetProp {
            id: 10,
            prop: Prop::Native(NativeProp::Src(Some(
                "//docs.example.com/v/../v.mp4".into(),
            ))),
        },
        Op::Insert {
            parent: ROOT_ID,
            child: 10,
            before: None,
        },
    ]);
    apply(&mut c, ops);
    let batch = c.commit().unwrap();
    let images: Vec<_> = batch
        .items
        .iter()
        .filter_map(|i| match i {
            MountItem::Image { id, source, .. } => {
                Some((*id, source.as_ref().map(|s| s.uri.to_string())))
            }
            _ => None,
        })
        .collect();
    assert_eq!(
        images,
        [
            (2, Some("https://docs.example.com/x.png".to_owned())),
            (4, None),
            (6, None),
            (8, Some("asset:/own.png".to_owned())),
        ]
    );
    let video = batch.items.iter().rev().find_map(|i| match i {
        MountItem::NativeProps {
            id: 10,
            props: crate::NativeProps::Video(p),
        } => Some(p.source.clone()),
        _ => None,
    });
    assert_eq!(
        video.flatten().as_deref(),
        Some("https://docs.example.com/v.mp4")
    );
}

