    #[test]
    fn a_js_host_of_a_rooted_component_takes_the_apps_styles_events_and_children() {
        let mut c = core();
        let mut registry = Registry::new();
        registry.register::<Tray>();
        registry.register::<Plaque>();
        c.set_components(registry);
        apply(
            &mut c,
            vec![
                Op::Create {
                    id: 2,
                    tag: Tag::View,
                },
                Op::SetProp {
                    id: 2,
                    prop: Prop::Component(std::any::type_name::<Plaque>().into()),
                },
                Op::SetProp {
                    id: 2,
                    prop: Prop::Class("opacity-25".into()),
                },
                Op::Insert {
                    parent: ROOT_ID,
                    child: 2,
                    before: None,
                },
            ],
        );
        let batch = c.commit().unwrap();
        // The app's class goes after what the view gives the counter.
        assert_eq!(view_style_of(&batch, 2).map(|s| s.opacity), Some(0.25));
        // JS stops listening to presses: the counter's view still does.
        apply(
            &mut c,
            vec![
                Op::Listen {
                    id: 2,
                    event: EventKind::Press,
                    enabled: true,
                },
                Op::Listen {
                    id: 2,
                    event: EventKind::Press,
                    enabled: false,
                },
            ],
        );
        c.commit();
        let key = c.key(2).unwrap();
        assert!(c.nodes[key as usize].events.contains(EventKind::Press));
        // The app's classes change: the node follows.
        c.apply(Op::SetProp {
            id: 2,
            prop: Prop::Class("opacity-75".into()),
        })
        .unwrap();
        let batch = c.commit().unwrap();
        assert_eq!(view_style_of(&batch, 2).map(|s| s.opacity), Some(0.75));
        // A tray: JS's children go into the host itself.
        apply(
            &mut c,
            vec![
                Op::Create {
                    id: 4,
                    tag: Tag::View,
                },
                Op::SetProp {
                    id: 4,
                    prop: Prop::Component(std::any::type_name::<Tray>().into()),
                },
                Op::Insert {
                    parent: ROOT_ID,
                    child: 4,
                    before: None,
                },
                Op::Create {
                    id: 6,
                    tag: Tag::View,
                },
                Op::Insert {
                    parent: 4,
                    child: 6,
                    before: None,
                },
            ],
        );
        let batch = c.commit().unwrap();
        assert_eq!(native_parent(&c, 6), Some(4));
        assert_eq!(creates(&batch), 2, "{:?}", batch.items);
        // Released: its nodes go, JS's child stays.
        apply(
            &mut c,
            vec![
                Op::Remove {
                    parent: ROOT_ID,
                    child: 4,
                },
                Op::Release { id: 4 },
                Op::Release { id: 2 },
            ],
        );
        let batch = c.commit().unwrap();
        assert!(c.key(6).is_ok());
        assert_eq!(native_parent(&c, 6), None);
        assert!(c.components.instances.is_empty());
        let deleted: Vec<NodeId> = batch
            .items
            .iter()
            .filter_map(|i| match i {
                MountItem::Delete { id } => Some(*id),
                _ => None,
            })
            .collect();
        assert!(deleted.contains(&2) && deleted.contains(&4), "{deleted:?}");
        assert_eq!(c.nodes.len(), 2, "the root and JS's child are left");
    }

    /// Places its corner slot as it is after a title, or padded when
    /// `framed`.
    #[derive(Default)]
    struct Corner;

    #[derive(Clone, PartialEq, Props)]
    struct CornerProps {
        #[prop(default)]
        framed: bool,
        corner: crate::element::Prop<Option<Slot>>,
    }

    impl Component for Corner {
        type Props = CornerProps;
        type Event = NoEvent;

        fn view(props: CornerProps, _: Scope<NoEvent>) -> impl IntoElement {
            let framed = props.framed;
            view().child(text("title")).child(
                props
                    .corner
                    .place(move |c| if framed { c.p_2() } else { c }),
            )
        }
    }

    /// Fills corners: with a counter, with what a press switches (a
    /// text, a view of a text), with a text shown while on, and framed.
    #[derive(Default)]
    struct Corners;

    #[derive(Clone, PartialEq, Props)]
    struct CornersProps {}

    impl Component for Corners {
        type Props = CornersProps;
        type Event = NoEvent;

        fn view(_: CornersProps, _: Scope<NoEvent>) -> impl IntoElement {
            let n = signal(0);
            view()
                .on_press(move || n.update(|n| *n += 1))
                .child(Corner::element(CornerProps::default()).fill(
                    "corner",
                    Counter::element(CounterProps {
                        label: "Aside".into(),
                    }),
                ))
                .child(dynamic(move || {
                    // A corner each run, filled anew.
                    let fill = if n.get() % 2 == 0 {
                        text("even").into_element()
                    } else {
                        view().child(text("odd")).into_element()
                    };
                    Corner::element(CornerProps::default()).fill("corner", fill)
                }))
                .child(Corner::element(CornerProps::default()).fill(
                    "corner",
                    dynamic(move || (n.get() == 1).then(|| text("one"))),
                ))
                .child(
                    Corner::element(CornerProps {
                        framed: true,
                        ..Default::default()
                    })
                    .fill("corner", text("framed")),
                )
        }
    }

    #[test]
    fn a_slot_a_view_fills_is_placed_as_it_is() {
        let mut c = core();
        c.mount_root(&Root::new::<Corners>(|| CornersProps {}));
        let batch = c.commit().unwrap();
        let root = root_host(&batch);
        let corners = native_children(&c, root);
        assert_eq!(corners.len(), 4);
        // The third corner's fill shows nothing: its title alone.
        assert_eq!(native_children(&c, corners[2]).len(), 1);
        // The counter's host is the corner's child: no holder.
        let counted = native_parent(&c, text_node(&batch, "Aside 0")).expect("placed");
        assert_eq!(native_parent(&c, counted), Some(corners[0]));
        assert_eq!(native_children(&c, corners[0]).len(), 2);
        assert_eq!(
            native_parent(&c, text_node(&batch, "even")),
            Some(corners[1])
        );
        // Styled: in a node of the corner's own.
        let framed = native_parent(&c, text_node(&batch, "framed")).expect("placed");
        assert_ne!(framed, corners[3]);
        assert_eq!(native_parent(&c, framed), Some(corners[3]));
        // Its listener and events are its own.
        assert!(c.component_event(counted, EventKind::Press, &EventPayload::None));
        assert_eq!(texts(&c.commit().unwrap()), ["Aside 1"]);
        // Filled anew: the new element takes the old one's place.
        assert!(c.component_event(root, EventKind::Press, &EventPayload::None));
        let batch = c.commit().unwrap();
        let odd = native_parent(&c, text_node(&batch, "odd")).expect("placed");
        let corners = native_children(&c, root);
        assert_eq!(native_parent(&c, odd), Some(corners[1]));
        assert_eq!(native_children(&c, corners[1]).len(), 2);
        // A fill that shows something now: placed in its corner.
        let one = text_node(&batch, "one");
        assert_eq!(native_parent(&c, one), Some(corners[2]));
        // And gone again (released with no holder to leave); even again.
        assert!(c.component_event(root, EventKind::Press, &EventPayload::None));
        let batch = c.commit().unwrap();
        assert!(c.key(one).is_err(), "released");
        assert!(
            !batch
                .items
                .iter()
                .any(|i| matches!(i, MountItem::Remove { .. })),
            "{:?}",
            batch.items
        );
        let corners = native_children(&c, root);
        assert_eq!(native_children(&c, corners[2]).len(), 1, "the title alone");
        let even = text_node(&batch, "even");
        assert_eq!(native_parent(&c, even), Some(corners[1]));
        assert_eq!(native_children(&c, corners[1]).len(), 2);
    }

    /// A row 300 × 40: its label slot made a button (no styles), then a 50 ×
    /// 20 box.
    #[derive(Default)]
    struct LabeledRow;

    #[derive(Clone, PartialEq, Props)]
    struct LabeledRowProps {
        label: crate::element::Prop<Option<Slot>>,
    }

    impl Component for LabeledRow {
        type Props = LabeledRowProps;
        type Event = NoEvent;

        fn view(props: LabeledRowProps, _: Scope<NoEvent>) -> impl IntoElement {
            view()
                .flex_row()
                .items_center()
                .w(px(300.0))
                .h(px(40.0))
                .child(
                    props
                        .label
                        .place(|c| c.role(crate::AccessibilityRole::Button)),
                )
                .child(view().w(px(50.0)).h(px(20.0)))
        }
    }

    /// Fills a row's label with a text that grows.
    #[derive(Default)]
    struct GrowingLabel;

    #[derive(Clone, PartialEq, Props)]
    struct GrowingLabelProps {}

    impl Component for GrowingLabel {
        type Props = GrowingLabelProps;
        type Event = NoEvent;

        fn view(_: GrowingLabelProps, _: Scope<NoEvent>) -> impl IntoElement {
            LabeledRow::element(LabeledRowProps::default()).fill("label", text("grow").flex_1())
        }
    }

    /// The node a view wraps its fill of a slot in when the place gives it
    /// props but no styles lays the fill out through: the fill grows along
    /// the row as the component's own child would, the wrapper takes its
    /// box and the fill sits at its origin.
    #[test]
    fn a_fill_in_a_wrapper_lays_out_in_the_components_layout() {
        let mut c = core();
        c.mount_root(&Root::new::<GrowingLabel>(|| GrowingLabelProps {}));
        let batch = c.commit().unwrap();
        let grow = text_node(&batch, "grow");
        let wrapper = native_parent(&c, grow).expect("placed");
        let row = native_parent(&c, wrapper).expect("placed");
        assert_eq!(native_children(&c, row).len(), 2, "the wrapper and the box");
        let wrapped = frame_of(&batch, wrapper).expect("a frame");
        assert_eq!(
            (wrapped.origin.x.0, wrapped.size.width.0),
            (0.0, 250.0),
            "grows to the box"
        );
        let grown = frame_of(&batch, grow).expect("a frame");
        assert_eq!(
            (grown.origin.x.0, grown.origin.y.0, grown.size.width.0),
            (0.0, 0.0, 250.0)
        );
        assert_eq!(grown.size.height, wrapped.size.height);
    }

    #[derive(Clone, PartialEq, Props)]
    struct MidProps {
        corner: crate::element::Prop<Option<Slot>>,
    }

    /// Passes its corner slot on to a corner's.
    #[component]
    fn Mid(props: MidProps) -> impl IntoElement {
        view().child(
            Corner::element(CornerProps::default()).fill("corner", props.corner.place(|c| c)),
        )
    }

    /// Fills a mid's corner with a text, and another's with what a press
    /// switches (a text, nothing, a view of a text).
    #[component]
    fn Top() -> impl IntoElement {
        let n = signal(0);
        view()
            .on_press(move || n.update(|n| *n += 1))
            .child(mid().corner(text("deep")))
            .child(mid().corner(dynamic(move || match n.get() % 3 {
                0 => Some(text("switched").into_element()),
                1 => None,
                _ => Some(view().child(text("boxed")).into_element()),
            })))
    }

    #[test]
    fn a_filled_slot_passed_on_to_another_slot_is_placed_there() {
        let mut c = core();
        c.mount_root(&Root::new::<Top>(|| ()));
        let batch = c.commit().unwrap();
        let top = root_host(&batch);
        // Each mid's view is its corner.
        let mids = native_children(&c, top);
        let [first, second] = [0, 1].map(|i| native_children(&c, mids[i])[0]);
        let deep = text_node(&batch, "deep");
        assert_eq!(native_parent(&c, deep), Some(first), "{:?}", batch.items);
        let switched = text_node(&batch, "switched");
        assert_eq!(native_parent(&c, switched), Some(second));
        // Gone, then a view of a text: the deeper corner follows.
        assert!(c.component_event(top, EventKind::Press, &EventPayload::None));
        c.commit().unwrap();
        assert_eq!(native_children(&c, second).len(), 1, "the title alone");
        assert!(c.component_event(top, EventKind::Press, &EventPayload::None));
        let batch = c.commit().unwrap();
        let boxed = native_parent(&c, text_node(&batch, "boxed")).expect("placed");
        assert_eq!(native_parent(&c, boxed), Some(second), "{:?}", batch.items);
    }

    /// A corner as its view's root, its fill switched by a press on it
    /// (a text, a view of a text).
    #[component]
    fn RootedCorner() -> impl IntoElement {
        let on = signal(true);
        let flip = move || on.update(|o| *o = !*o);
        Corner::element(CornerProps::default()).fill(
            "corner",
            dynamic(move || {
                if on.get() {
                    text("x").on_press(flip).into_element()
                } else {
                    view().on_press(flip).child(text("y")).into_element()
                }
            }),
        )
    }

    #[test]
    fn a_component_rooted_in_another_fills_its_slot() {
        let mut c = core();
        c.mount_root(&Root::new::<RootedCorner>(|| ()));
        let batch = c.commit().unwrap();
        let host = root_host(&batch);
        assert_eq!(native_parent(&c, text_node(&batch, "x")), Some(host));
        assert_eq!(native_children(&c, host).len(), 2);
        for round in 0..4 {
            let fill = native_children(&c, host)[1];
            assert!(c.component_event(fill, EventKind::Press, &EventPayload::None));
            let batch = c.commit().unwrap();
            assert_eq!(
                native_children(&c, host).len(),
                2,
                "{round}: {:?}",
                batch.items
            );
        }
    }

    #[derive(Clone, PartialEq, Props)]
    struct FocusCornerProps {
        corner: crate::element::Prop<Option<Slot>>,
    }

    /// Counts the focus its corner gets and loses: listeners the place
    /// gives the slot.
    #[component]
    fn FocusCorner(props: FocusCornerProps) -> impl IntoElement {
        let (focused, blurred) = (signal(0), signal(0));
        view()
            .child(text(move || {
                format!("focus {} blur {}", focused.get(), blurred.get())
            }))
            .child(props.corner.place(move |c| {
                c.on_focus(move || focused.update(|n| *n += 1))
                    .on_blur(move || blurred.update(|n| *n += 1))
            }))
    }

    /// Fills a focus corner with a focusable view it counts the presses
    /// of, then (pressing "switch") with a focusable text in its place.
    #[component]
    fn FocusTop() -> impl IntoElement {
        let (presses, second) = (signal(0), signal(false));
        let press = move || presses.update(|n| *n += 1);
        view()
            .child(text(move || format!("pressed {}", presses.get())))
            .child(focus_corner().corner(dynamic(move || {
                if second.get() {
                    text("second").focusable(true).into_element()
                } else {
                    view()
                        .focusable(true)
                        .on_press(press)
                        .child(text("first"))
                        .into_element()
                }
            })))
            .child(
                view()
                    .on_press(move || second.set(true))
                    .child(text("switch")),
            )
    }

    /// A slot a Rust view fills with one element, whose place gives it
    /// listeners: they go to that element as to a TSX app's in its holder
    /// (the node around the fill keeps none), so the focus, which only the
    /// focused element hears, reaches the component; the element's own
    /// listeners run too, and an element made in its place takes them.
    #[test]
    fn a_fills_one_element_hears_the_listeners_its_place_gives() {
        let events = |c: &Core<FakeEngine>, id: NodeId| c.nodes[c.key(id).unwrap() as usize].events;
        let mut c = core();
        c.mount_root(&Root::new::<FocusTop>(|| ()));
        let batch = c.commit().unwrap();
        let switch = native_parent(&c, text_node(&batch, "switch")).expect("placed");
        let first = native_parent(&c, text_node(&batch, "first")).expect("placed");
        let holder = native_parent(&c, first).expect("in the node around the fill");
        assert!(events(&c, first).contains(EventKind::Focus));
        assert!(events(&c, first).contains(EventKind::Blur));
        assert!(events(&c, first).contains(EventKind::Press), "its own");
        assert!(!events(&c, holder).contains(EventKind::Focus));
        assert!(c.component_event(first, EventKind::Focus, &EventPayload::None));
        assert!(c.component_event(first, EventKind::Blur, &EventPayload::None));
        assert!(c.component_event(first, EventKind::Press, &EventPayload::None));
        let shown = texts(&c.commit().unwrap());
        assert!(shown.contains(&"focus 1 blur 1".into()), "{shown:?}");
        assert!(shown.contains(&"pressed 1".into()), "{shown:?}");
        // Another element in its place: the listeners follow it.
        assert!(c.component_event(switch, EventKind::Press, &EventPayload::None));
        let batch = c.commit().unwrap();
        let second = text_node(&batch, "second");
        assert!(c.key(first).is_err(), "released");
        assert_eq!(native_parent(&c, second), Some(holder));
        assert!(events(&c, second).contains(EventKind::Focus));
        assert!(!events(&c, holder).contains(EventKind::Focus));
        assert!(c.component_event(second, EventKind::Focus, &EventPayload::None));
        let shown = texts(&c.commit().unwrap());
        assert!(shown.contains(&"focus 2 blur 1".into()), "{shown:?}");
    }

    /// Logs the focus coming into its area and leaving it, and dims the
    /// area while the focus is in it: two focusable views and a popup
    /// inside, one outside.
    #[component]
    fn FocusArea() -> impl IntoElement {
        let log = signal(Vec::<&'static str>::new());
        let area = element_ref();
        area.on_focus_in(move || log.update(|l| l.push("in")));
        area.on_focus_out(move || log.update(|l| l.push("out")));
        view()
            .child(text(move || format!("log {}", log.get().join(" "))))
            .child(
                view()
                    .element_ref(&area)
                    .focus_within(|s| s.opacity(0.5))
                    .child(view().focusable(true).child(text("first")))
                    .child(view().focusable(true).child(text("second")))
                    .child(overlay().child(view().focusable(true).child(text("popup")))),
            )
            .child(view().focusable(true).child(text("away")))
    }

    /// GPUI's `on_focus_in` / `on_focus_out` of an element: the focus
    /// coming in from outside and leaving to outside, not moving inside it
    /// (into its popup too); `.focus_within(..)` styles it meanwhile.
    #[test]
    fn an_element_hears_the_focus_come_in_and_leave() {
        use crate::tailwind::state::FOCUSED;
        let mut c = core();
        c.mount_root(&Root::new::<FocusArea>(|| ()));
        let batch = c.commit().unwrap();
        let first = native_parent(&c, text_node(&batch, "first")).unwrap();
        let second = native_parent(&c, text_node(&batch, "second")).unwrap();
        let popup = native_parent(&c, text_node(&batch, "popup")).unwrap();
        let away = native_parent(&c, text_node(&batch, "away")).unwrap();
        let area = native_parent(&c, first).unwrap();
        c.set_states(first, FOCUSED);
        let batch = c.commit().unwrap();
        assert!(
            texts(&batch).contains(&"log in".into()),
            "{:?}",
            texts(&batch)
        );
        assert_eq!(view_style_of(&batch, area).unwrap().opacity, 0.5);
        c.set_states(second, FOCUSED);
        c.set_states(first, 0);
        c.set_states(popup, FOCUSED);
        c.set_states(second, 0);
        let batch = c.commit();
        assert!(batch.is_none_or(|b| texts(&b).is_empty()), "no news inside");
        c.set_states(away, FOCUSED);
        c.set_states(popup, 0);
        let batch = c.commit().unwrap();
        assert!(
            texts(&batch).contains(&"log in out".into()),
            "{:?}",
            texts(&batch)
        );
        assert_eq!(view_style_of(&batch, area).unwrap().opacity, 1.0);
        // Back in: the area's own state again.
        c.set_states(popup, FOCUSED);
        c.set_states(away, 0);
        let batch = c.commit().unwrap();
        assert!(
            texts(&batch).contains(&"log in out in".into()),
            "{:?}",
            texts(&batch)
        );
    }

    #[derive(Clone, PartialEq, Props)]
    struct AnchoredCornerProps {
        corner: crate::element::Prop<Option<Slot>>,
        #[prop(default)]
        open: crate::element::Prop<bool>,
    }

    /// Gives its corner a ref and, while `open`, shows a 40 × 20 overlay
    /// 4 points below what the corner draws, from its start (a popover's).
    #[component]
    fn AnchoredCorner(props: AnchoredCornerProps) -> impl IntoElement {
        let anchor = element_ref();
        view()
            .child(props.corner.place(move |c| c.element_ref(&anchor)))
            .child(when(
                move || props.open.get(),
                move || {
                    overlay()
                        .anchor_content(&anchor)
                        .placement(Placement::Bottom)
                        .align(Align::Start)
                        .offset(px(4.0))
                        .w(px(40.0))
                        .h(px(20.0))
                        .child(text("pop"))
                },
            ))
    }

    /// Fills an anchored corner, 100 points down, with an 80 × 30 view
    /// around a 50 × 10 box; a press on the root opens its overlay.
    #[component]
    fn AnchoredTop() -> impl IntoElement {
        let open = signal(false);
        view().pt(px(100.0)).on_press(move || open.set(true)).child(
            anchored_corner().open(open).corner(
                view()
                    .w(px(80.0))
                    .h(px(30.0))
                    .child(view().w(px(50.0)).h(px(10.0)).child(text("box"))),
            ),
        )
    }

    /// The ref a component gives a slot a Rust view fills is the filled
    /// element's, not its child's, and an overlay placed against what the
    /// slot draws goes by the element's own box (its size, not its
    /// content's), as it did while the ref was on the node around it.
    #[test]
    fn a_fills_element_takes_the_slots_ref_with_its_own_box() {
        let mut c = core();
        c.mount_root(&Root::new::<AnchoredTop>(|| ()));
        let batch = c.commit().unwrap();
        let top = root_host(&batch);
        let inner = native_parent(&c, text_node(&batch, "box")).expect("placed");
        let element = native_parent(&c, inner).expect("placed");
        let holder = native_parent(&c, element).expect("in the node around the fill");
        assert_eq!(
            c.components.adopted.get(&element),
            Some(&holder),
            "the element takes the slot's props"
        );
        assert!(c.component_event(top, EventKind::Press, &EventPayload::None));
        let batch = c.commit().unwrap();
        let pop = native_parent(&c, text_node(&batch, "pop")).expect("shown");
        // Below the element (0, 100, 80 × 30), not its 10-point box.
        assert_eq!(frame_of(&batch, pop), Some(rect(0.0, 134.0, 40.0, 20.0)));
    }

    /// Rows of a list, each with a filled corner, a holder of a text and a
    /// plaque.
    #[component]
    fn FilledRows() -> impl IntoElement {
        view().flex_1().child(
            virtual_list(200, move |at| {
                let i = at.index();
                view()
                    .h(px(40.0))
                    .child(
                        Corner::element(CornerProps::default())
                            .fill("corner", text(format!("r{i}"))),
                    )
                    .child(
                        Holder::element(HolderProps {
                            children: Children::default(),
                        })
                        .child(text(format!("h{i}"))),
                    )
                    .child(Plaque::element(PlaqueProps {}))
            })
            .estimated_item_size(px(40.0))
            .flex_1(),
        )
    }

    #[test]
    fn list_rows_with_filled_slots_follow_their_rows() {
        let mut c = core();
        c.mount_root(&Root::new::<FilledRows>(|| ()));
        let batch = c.commit().unwrap();
        let list = batch
            .items
            .iter()
            .find_map(|i| match i {
                MountItem::Create {
                    id,
                    kind: ViewKind::Scroll,
                } => Some(*id),
                _ => None,
            })
            .expect("a list");
        let mut shown: std::collections::HashMap<String, NodeId> = Default::default();
        let record = |b: &MountBatch, shown: &mut std::collections::HashMap<String, NodeId>| {
            for i in &b.items {
                if let MountItem::Text { id, text, .. } = i {
                    shown.retain(|_, v| v != id);
                    shown.insert(text.text.clone(), *id);
                }
            }
        };
        record(&batch, &mut shown);
        let mut sizes = Vec::new();
        for step in 1..=12u32 {
            let y = (step as f32 * 900.0) % 7000.0;
            c.set_scroll_offset(list, point(px(0.0), px(y)), u32::MAX);
            for _ in 0..3 {
                if let Some(b) = c.commit() {
                    record(&b, &mut shown);
                }
            }
            sizes.push((c.nodes.len(), c.components.instances.len()));
            // Every r<i> shown is in the corner of the row showing h<i>.
            for (t, &id) in &shown {
                let Some(n) = t.strip_prefix('r') else {
                    continue;
                };
                if c.key(id).is_err() {
                    continue;
                }
                let Some(corner) = native_parent(&c, id) else {
                    continue;
                };
                let row = native_parent(&c, corner).expect("a corner in a row");
                if let Some(&h) = shown.get(&format!("h{n}"))
                    && c.key(h).is_ok()
                {
                    let holder = native_parent(&c, h).unwrap();
                    assert_eq!(native_parent(&c, holder), Some(row), "{step}: {t} and h{n}");
                }
            }
        }
        assert!(
            sizes
                .windows(2)
                .skip(2)
                .all(|w| w[0].0.abs_diff(w[1].0) < 40),
            "{sizes:?}"
        );
        assert_eq!(sizes[3].1, sizes[sizes.len() - 1].1, "{sizes:?}");
    }

    /// A chat of 50 messages of 60 pt, estimated at 170 pt.
    #[component]
    fn Chat() -> impl IntoElement {
        messages(60.0)
    }

    /// The same chat, its newest message longer than the screen.
    #[component]
    fn LongChat() -> impl IntoElement {
        messages(900.0)
    }

    fn messages(newest: f32) -> impl IntoElement {
        view().flex_1().child(
            virtual_list(50, move |at| {
                let i = at.index();
                text(format!("m{i}")).h(px(if i == 49 { newest } else { 60.0 }))
            })
            .estimated_item_size(px(170.0))
            .initial_scroll_at_end()
            .flex_1(),
        )
    }

    /// Mounts `root`'s chat and follows its list as a platform would, the
    /// offset clamped to the content: the texts of the first batch, and
    /// where the list ends against where its content ends.
    fn open_chat(root: &Root) -> (Vec<String>, f32, f32) {
        let mut c = core();
        c.mount_root(root);
        let first = c.commit().unwrap();
        let list = first
            .items
            .iter()
            .find_map(|i| match i {
                MountItem::Create {
                    id,
                    kind: ViewKind::Scroll,
                } => Some(*id),
                _ => None,
            })
            .expect("a list");
        let texts = first
            .items
            .iter()
            .filter_map(|i| match i {
                MountItem::Text { text, .. } => Some(text.text.clone()),
                _ => None,
            })
            .collect();
        let (mut at, mut content) = (0.0_f32, 0.0_f32);
        let mut apply = |b: &MountBatch| {
            for item in &b.items {
                let max = (content - 480.0).max(0.0);
                match item {
                    MountItem::ScrollContent { id, size } if *id == list => {
                        content = size.height.0;
                        at = at.min((content - 480.0).max(0.0));
                    }
                    MountItem::Command {
                        id,
                        command: Command::ScrollTo { y, .. },
                    } if *id == list => at = y.0.clamp(0.0, max),
                    MountItem::ScrollBy { id, dy, .. } if *id == list => {
                        at = (at + dy.0).clamp(0.0, max);
                    }
                    _ => {}
                }
            }
        };
        apply(&first);
        while let Some(batch) = c.commit() {
            apply(&batch);
        }
        (texts, at, content - 480.0)
    }

    #[test]
    fn a_list_opens_at_its_end_and_stays_there_as_rows_measure() {
        // Rows shorter than estimated shrink the content under the jump;
        // a newest row longer than the screen opens at its end, not its top.
        for root in [Root::new::<Chat>(|| ()), Root::new::<LongChat>(|| ())] {
            let (texts, at, end) = open_chat(&root);
            // The first frame shows the newest message, not the first ones.
            assert!(texts.contains(&"m49".to_string()), "{texts:?}");
            assert!(!texts.contains(&"m0".to_string()), "{texts:?}");
            assert_eq!(at, end);
            assert_ne!(end, 50.0 * 170.0 - 480.0, "rows were measured");
        }
    }

