#[test]
fn an_anchored_overlay_lands_on_whole_device_pixels() {
    use StyleValue::Number;
    for ratio in [1.0, 2.0, 3.0] {
        let mut c = core();
        at_ratio(&mut c, ratio);
        add(&mut c, 2, Tag::View, ROOT_ID, &[("height", Number(480.0))]);
        add(&mut c, 10, Tag::Overlay, 2, &[]);
        add(
            &mut c,
            12,
            Tag::View,
            10,
            &[("width", Number(120.0)), ("height", Number(60.0))],
        );
        // A pointer between pixels, as a context menu opens at.
        apply(
            &mut c,
            vec![overlay_prop(
                10,
                crate::OverlayProp::Anchor(crate::overlay::OverlayAnchor::Point(point(
                    px(100.38),
                    px(50.71),
                ))),
            )],
        );
        let batch = c.commit().unwrap();
        let frame = frame_of(&batch, 10).expect("overlay frame");
        for v in [frame.origin.x.0, frame.origin.y.0] {
            let pixels = v * ratio;
            assert!(
                (pixels - pixels.round()).abs() < 1.0e-3,
                "{v} is not on a device pixel at {ratio}"
            );
        }
        // Still centred on the pointer (100.38 - 120 / 2), within a pixel.
        assert!((frame.origin.x.0 - 40.38).abs() <= 1.0 / ratio);
    }
}

#[test]
fn overlays_with_a_cover_lay_that_view_over_the_anchor() {
    use StyleValue::Number;
    let mut c = core();
    // A trigger 80 × 30 at (40, 100).
    add(
        &mut c,
        2,
        Tag::View,
        ROOT_ID,
        &[
            ("marginLeft", Number(40.0)),
            ("marginTop", Number(100.0)),
            ("width", Number(80.0)),
            ("height", Number(30.0)),
        ],
    );
    // A list of three 20-point rows under 4 points of padding.
    add(&mut c, 8, Tag::Overlay, ROOT_ID, &[]);
    add(
        &mut c,
        10,
        Tag::View,
        8,
        &[("width", Number(100.0)), ("padding", Number(4.0))],
    );
    for id in [12, 14, 16] {
        add(&mut c, id, Tag::View, 10, &[("height", Number(20.0))]);
    }
    apply(
        &mut c,
        vec![
            overlay_prop(
                8,
                crate::OverlayProp::Anchor(crate::overlay::OverlayAnchor::Node(2)),
            ),
            overlay_prop(8, crate::OverlayProp::Cover(Some(14))),
        ],
    );
    let batch = c.commit().unwrap();
    // At the trigger's start, the second row (4, 24 in the list) with
    // its middle on the trigger's.
    assert_eq!(frame_of(&batch, 8), Some(rect(40.0, 81.0, 100.0, 68.0)));
    // A row added before it moves it in the list: it is found again.
    add(&mut c, 18, Tag::View, 10, &[("height", Number(20.0))]);
    apply(
        &mut c,
        vec![Op::Insert {
            parent: 10,
            child: 18,
            before: Some(12),
        }],
    );
    let batch = c.commit().unwrap();
    assert_eq!(frame_of(&batch, 8), Some(rect(40.0, 61.0, 100.0, 88.0)));
}

#[test]
