    assert!(bound_items(&c, 4).is_empty());
    let mut binds = Vec::new();
    c.take_list_binds(&mut binds);
    assert!(binds.is_empty());
    c.set_scroll_offset(2, point(px(0.0), px(1700.0)), 0);
